-- ----------------------------------------------------------------------------
-- Individuals: Ancestrally diverse cohort participants whose phased genomes, omics profiles, exposures, and clinical phenotypes feed causal architecture inference.
-- ----------------------------------------------------------------------------
INSERT INTO individuals (individual_id, given_name, family_name, ancestry_label, age_years, is_ancestry_absent_from_training, federated_dataset, enrollment_date, has_cryptic_relatedness_flag, genomic_variants, omics_assays, environmental_exposures, treatments, clinical_phenotypes, causal_mechanisms, epistatic_interactions, counterfactual_trajectories, individual_predictions, case_narrative)
VALUES ('ind-a-reyes', 'Ana', 'Reyes', 'European', 34, FALSE, 'fed-europe', '2023-04-10', FALSE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Ana Reyes, a 34-year-old woman of European ancestry (cohort is in the training set), presents with photosensitive malar rash, arthralgia, and a positive ANA, raising concern for SLE onset. Family history is notable for lupus in a maternal aunt. Genotyping finds the IRF5 regulatory variant rs2004640 at an allele frequency of 0.006 (rare), and allele-specific expression is present at the locus. Functional workup of the IRF5 -> type-I interferon -> SLE-risk edge returns a cis-eQTL in blood RNA-seq with effect 0.91 (SE 0.20), a caQTL in blood ATAC-seq with effect 0.73 (SE 0.19), and a pQTL in blood proteomics with effect 0.66 (SE 0.20) — three assays across two omics modalities, all ancestry-PC and batch adjusted. The edge replicates with a positive effect sign in an East Asian cohort (p=0.004) and in an African cohort (p=0.013), while a European replication is directionally consistent but not significant (p=0.18). Two ancestry-permutation negative controls collapse to the null (permutation effect 0.012 and 0.028, well inside the +/-0.1 null band). The IL-interferon target is druggable (anifrolumab, anti-IFNAR1), giving a perturbable intervention target. For SLE-onset risk, the model''s reliability bins each carry coverage of 29-34 held-out individuals, with observed event rates tracking predicted bands closely (e.g. 0.09 observed at the 0.1 band, 0.88 at the 0.9 band). No cryptic-relatedness or assortative-mating leakage was flagged.') ON CONFLICT (individual_id) DO UPDATE SET given_name = EXCLUDED.given_name, family_name = EXCLUDED.family_name, ancestry_label = EXCLUDED.ancestry_label, age_years = EXCLUDED.age_years, is_ancestry_absent_from_training = EXCLUDED.is_ancestry_absent_from_training, federated_dataset = EXCLUDED.federated_dataset, enrollment_date = EXCLUDED.enrollment_date, has_cryptic_relatedness_flag = EXCLUDED.has_cryptic_relatedness_flag, genomic_variants = EXCLUDED.genomic_variants, omics_assays = EXCLUDED.omics_assays, environmental_exposures = EXCLUDED.environmental_exposures, treatments = EXCLUDED.treatments, clinical_phenotypes = EXCLUDED.clinical_phenotypes, causal_mechanisms = EXCLUDED.causal_mechanisms, epistatic_interactions = EXCLUDED.epistatic_interactions, counterfactual_trajectories = EXCLUDED.counterfactual_trajectories, individual_predictions = EXCLUDED.individual_predictions, case_narrative = EXCLUDED.case_narrative;

INSERT INTO individuals (individual_id, given_name, family_name, ancestry_label, age_years, is_ancestry_absent_from_training, federated_dataset, enrollment_date, has_cryptic_relatedness_flag, genomic_variants, omics_assays, environmental_exposures, treatments, clinical_phenotypes, causal_mechanisms, epistatic_interactions, counterfactual_trajectories, individual_predictions, case_narrative)
VALUES ('ind-b-okafor', 'Bili', 'Okafor', 'European', 41, FALSE, 'fed-europe', '2023-05-12', FALSE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Bili Okafor, a 41-year-old man of European ancestry (in the training set), presents with serositis, fatigue, and a high-titre ANA suggestive of SLE onset. Genotyping finds the IRF5 regulatory variant rs2004640 at an allele frequency of 0.006 (rare), with allele-specific expression present. The IRF5 -> type-I interferon -> SLE-risk edge is supported by a cis-eQTL in blood RNA-seq with effect 0.84 (SE 0.21), a caQTL in blood ATAC-seq with effect 0.79 (SE 0.20), and a pQTL in blood proteomics with effect 0.58 (SE 0.20), spanning two omics modalities and adjusted for ancestry PCs and batch. It replicates positive in an East Asian cohort (p=0.006) and an African cohort (p=0.017), with a non-significant European replication (p=0.22). Two ancestry-permutation controls collapse to the null (permutation effect 0.015 and 0.024 inside +/-0.1). The interferon target is druggable. The mechanism is as solid as Ana''s — but the calibration substrate is thin: this site only accrued coverage of 7-14 held-out individuals per reliability bin, far below the 20-count floor needed to trust the predicted-vs-observed match. No cryptic-relatedness leakage was flagged.') ON CONFLICT (individual_id) DO UPDATE SET given_name = EXCLUDED.given_name, family_name = EXCLUDED.family_name, ancestry_label = EXCLUDED.ancestry_label, age_years = EXCLUDED.age_years, is_ancestry_absent_from_training = EXCLUDED.is_ancestry_absent_from_training, federated_dataset = EXCLUDED.federated_dataset, enrollment_date = EXCLUDED.enrollment_date, has_cryptic_relatedness_flag = EXCLUDED.has_cryptic_relatedness_flag, genomic_variants = EXCLUDED.genomic_variants, omics_assays = EXCLUDED.omics_assays, environmental_exposures = EXCLUDED.environmental_exposures, treatments = EXCLUDED.treatments, clinical_phenotypes = EXCLUDED.clinical_phenotypes, causal_mechanisms = EXCLUDED.causal_mechanisms, epistatic_interactions = EXCLUDED.epistatic_interactions, counterfactual_trajectories = EXCLUDED.counterfactual_trajectories, individual_predictions = EXCLUDED.individual_predictions, case_narrative = EXCLUDED.case_narrative;

INSERT INTO individuals (individual_id, given_name, family_name, ancestry_label, age_years, is_ancestry_absent_from_training, federated_dataset, enrollment_date, has_cryptic_relatedness_flag, genomic_variants, omics_assays, environmental_exposures, treatments, clinical_phenotypes, causal_mechanisms, epistatic_interactions, counterfactual_trajectories, individual_predictions, case_narrative)
VALUES ('ind-c-chen', 'Chen', 'Wei', 'East Asian', 47, FALSE, 'fed-east-asia', '2022-09-01', FALSE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Chen Wei, a 47-year-old woman of East Asian ancestry (in the training set), presents with arthritis, oral ulcers, and anti-dsDNA positivity concerning for SLE onset. Genotyping finds the STAT4 regulatory variant rs7574865 at an allele frequency of 0.008 (rare), with allele-specific expression present. The STAT4 -> Th1/IFN -> SLE-risk edge shows a cis-eQTL in blood RNA-seq with effect 1.02 (SE 0.23), a caQTL in blood ATAC-seq with effect 0.61 (SE 0.20), and a pQTL in blood proteomics with effect 0.55 (SE 0.21), across two modalities, ancestry-PC and batch adjusted. Replication is troubling: the effect is positive in an East Asian cohort (p=0.009) but the SIGN FLIPS to negative in an African cohort (p=0.024), and the European replication is non-significant (p=0.27) — only one concordant cohort. Worse, while one ancestry-permutation control collapses (permutation effect 0.013), a second negative control does NOT collapse: its permutation effect is 0.46, far outside the +/-0.1 null band, so the signal is not separable from permuted noise. Reliability bins carry coverage of 28-32 per bin. No cryptic-relatedness leakage was flagged.') ON CONFLICT (individual_id) DO UPDATE SET given_name = EXCLUDED.given_name, family_name = EXCLUDED.family_name, ancestry_label = EXCLUDED.ancestry_label, age_years = EXCLUDED.age_years, is_ancestry_absent_from_training = EXCLUDED.is_ancestry_absent_from_training, federated_dataset = EXCLUDED.federated_dataset, enrollment_date = EXCLUDED.enrollment_date, has_cryptic_relatedness_flag = EXCLUDED.has_cryptic_relatedness_flag, genomic_variants = EXCLUDED.genomic_variants, omics_assays = EXCLUDED.omics_assays, environmental_exposures = EXCLUDED.environmental_exposures, treatments = EXCLUDED.treatments, clinical_phenotypes = EXCLUDED.clinical_phenotypes, causal_mechanisms = EXCLUDED.causal_mechanisms, epistatic_interactions = EXCLUDED.epistatic_interactions, counterfactual_trajectories = EXCLUDED.counterfactual_trajectories, individual_predictions = EXCLUDED.individual_predictions, case_narrative = EXCLUDED.case_narrative;

INSERT INTO individuals (individual_id, given_name, family_name, ancestry_label, age_years, is_ancestry_absent_from_training, federated_dataset, enrollment_date, has_cryptic_relatedness_flag, genomic_variants, omics_assays, environmental_exposures, treatments, clinical_phenotypes, causal_mechanisms, epistatic_interactions, counterfactual_trajectories, individual_predictions, case_narrative)
VALUES ('ind-d-santos', 'Diego', 'Santos', 'European', 29, FALSE, 'fed-europe', '2024-01-20', TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Diego Santos, a 29-year-old man of European ancestry (in the training set), presents with nephritis and a malar rash concerning for SLE onset. Genotyping finds the IRF5 regulatory variant rs2004640 at an allele frequency of 0.006 (rare), with allele-specific expression present. The IRF5 -> type-I interferon -> SLE-risk edge is fully supported: a cis-eQTL in blood RNA-seq with effect 0.88 (SE 0.20), a caQTL in blood ATAC-seq with effect 0.95 (SE 0.21), and a pQTL in blood proteomics with effect 0.62 (SE 0.20), across two modalities and adjusted for ancestry PCs and batch. It replicates positive in an East Asian cohort (p=0.003) and an African cohort (p=0.019), with a non-significant European replication (p=0.16). Two ancestry-permutation controls collapse to the null (permutation effect 0.009 and 0.031 inside +/-0.1). The interferon target is druggable, and reliability bins carry coverage of 30-36 per bin. However, sample QC raised a cryptic-relatedness / assortative-mating flag for this participant: kinship estimates indicate undeclared relatives inside the cohort, so the prediction may be confounded by leakage rather than the mechanism alone.') ON CONFLICT (individual_id) DO UPDATE SET given_name = EXCLUDED.given_name, family_name = EXCLUDED.family_name, ancestry_label = EXCLUDED.ancestry_label, age_years = EXCLUDED.age_years, is_ancestry_absent_from_training = EXCLUDED.is_ancestry_absent_from_training, federated_dataset = EXCLUDED.federated_dataset, enrollment_date = EXCLUDED.enrollment_date, has_cryptic_relatedness_flag = EXCLUDED.has_cryptic_relatedness_flag, genomic_variants = EXCLUDED.genomic_variants, omics_assays = EXCLUDED.omics_assays, environmental_exposures = EXCLUDED.environmental_exposures, treatments = EXCLUDED.treatments, clinical_phenotypes = EXCLUDED.clinical_phenotypes, causal_mechanisms = EXCLUDED.causal_mechanisms, epistatic_interactions = EXCLUDED.epistatic_interactions, counterfactual_trajectories = EXCLUDED.counterfactual_trajectories, individual_predictions = EXCLUDED.individual_predictions, case_narrative = EXCLUDED.case_narrative;

INSERT INTO individuals (individual_id, given_name, family_name, ancestry_label, age_years, is_ancestry_absent_from_training, federated_dataset, enrollment_date, has_cryptic_relatedness_flag, genomic_variants, omics_assays, environmental_exposures, treatments, clinical_phenotypes, causal_mechanisms, epistatic_interactions, counterfactual_trajectories, individual_predictions, case_narrative)
VALUES ('ind-e-mensah', 'Esi', 'Mensah', 'African', 38, FALSE, 'fed-west-africa', '2023-07-15', FALSE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Esi Mensah, a 38-year-old woman of African ancestry (in the training set), presents with arthralgia and cytopenias concerning for SLE onset. Genotyping finds the CTLA4 enhancer variant rs3087243 at an allele frequency of 0.007 (rare), with allele-specific expression present. The CTLA4 -> T-cell costimulation -> SLE-risk edge is well supported: a cis-eQTL in blood RNA-seq with effect 0.79 (SE 0.21), a caQTL in blood ATAC-seq with effect 0.71 (SE 0.20), and a pQTL in blood proteomics with effect 0.41 (SE 0.20), across two modalities, ancestry-PC and batch adjusted. It replicates positive in an East Asian cohort (p=0.007) and a European cohort (p=0.021), with a non-significant African replication (p=0.19). Two ancestry-permutation controls collapse to the null (permutation effect 0.011 and 0.026 inside +/-0.1), and reliability bins carry coverage of 27-33 per bin. The gap is experimental: no perturbable intervention target has been mapped for this edge — there is no agent or assay that could knock the costimulation node down to test it, so the mechanism is not experimentally falsifiable as stated.') ON CONFLICT (individual_id) DO UPDATE SET given_name = EXCLUDED.given_name, family_name = EXCLUDED.family_name, ancestry_label = EXCLUDED.ancestry_label, age_years = EXCLUDED.age_years, is_ancestry_absent_from_training = EXCLUDED.is_ancestry_absent_from_training, federated_dataset = EXCLUDED.federated_dataset, enrollment_date = EXCLUDED.enrollment_date, has_cryptic_relatedness_flag = EXCLUDED.has_cryptic_relatedness_flag, genomic_variants = EXCLUDED.genomic_variants, omics_assays = EXCLUDED.omics_assays, environmental_exposures = EXCLUDED.environmental_exposures, treatments = EXCLUDED.treatments, clinical_phenotypes = EXCLUDED.clinical_phenotypes, causal_mechanisms = EXCLUDED.causal_mechanisms, epistatic_interactions = EXCLUDED.epistatic_interactions, counterfactual_trajectories = EXCLUDED.counterfactual_trajectories, individual_predictions = EXCLUDED.individual_predictions, case_narrative = EXCLUDED.case_narrative;

INSERT INTO individuals (individual_id, given_name, family_name, ancestry_label, age_years, is_ancestry_absent_from_training, federated_dataset, enrollment_date, has_cryptic_relatedness_flag, genomic_variants, omics_assays, environmental_exposures, treatments, clinical_phenotypes, causal_mechanisms, epistatic_interactions, counterfactual_trajectories, individual_predictions, case_narrative)
VALUES ('ind-f-haidar', 'Faisal', 'Haidar', 'Indigenous American', 31, TRUE, 'fed-amazon', '2025-02-01', FALSE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Faisal Haidar, a 31-year-old man of Indigenous American ancestry — an ancestry deliberately HELD OUT of the training set — presents with dactylitis, enthesitis, and nail pitting concerning for psoriatic-arthritis (PsA) onset. Genotyping finds the IL23R regulatory variant rs11209026 at an allele frequency of 0.009 (rare), with allele-specific expression present. The IL23R -> IL-17 axis -> PsA-risk edge is well supported: a cis-eQTL in blood RNA-seq with effect 1.07 (SE 0.20), a caQTL in blood ATAC-seq with effect 0.83 (SE 0.21), and a pQTL in blood proteomics with effect 0.74 (SE 0.20), across two modalities and adjusted for ancestry PCs and batch. The IL-17 target is druggable (secukinumab). Two ancestry-permutation controls collapse to the null (permutation effect 0.008 and 0.022 inside +/-0.1), and reliability bins carry coverage of 30-35 per bin. But every replication of this edge was run in an Indigenous American cohort: p=0.005, p=0.015, and p=0.034, all positive, all in the SAME ancestry. There is no cohort in a DIFFERENT ancestry confirming the effect — so for a patient whose ancestry is absent from training, nothing demonstrates the mechanism transports. No cryptic-relatedness leakage was flagged.') ON CONFLICT (individual_id) DO UPDATE SET given_name = EXCLUDED.given_name, family_name = EXCLUDED.family_name, ancestry_label = EXCLUDED.ancestry_label, age_years = EXCLUDED.age_years, is_ancestry_absent_from_training = EXCLUDED.is_ancestry_absent_from_training, federated_dataset = EXCLUDED.federated_dataset, enrollment_date = EXCLUDED.enrollment_date, has_cryptic_relatedness_flag = EXCLUDED.has_cryptic_relatedness_flag, genomic_variants = EXCLUDED.genomic_variants, omics_assays = EXCLUDED.omics_assays, environmental_exposures = EXCLUDED.environmental_exposures, treatments = EXCLUDED.treatments, clinical_phenotypes = EXCLUDED.clinical_phenotypes, causal_mechanisms = EXCLUDED.causal_mechanisms, epistatic_interactions = EXCLUDED.epistatic_interactions, counterfactual_trajectories = EXCLUDED.counterfactual_trajectories, individual_predictions = EXCLUDED.individual_predictions, case_narrative = EXCLUDED.case_narrative;

INSERT INTO individuals (individual_id, given_name, family_name, ancestry_label, age_years, is_ancestry_absent_from_training, federated_dataset, enrollment_date, has_cryptic_relatedness_flag, genomic_variants, omics_assays, environmental_exposures, treatments, clinical_phenotypes, causal_mechanisms, epistatic_interactions, counterfactual_trajectories, individual_predictions, case_narrative)
VALUES ('ind-g-lin', 'Grace', 'Lin', 'Indigenous American', 36, TRUE, 'fed-amazon', '2025-02-03', FALSE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Grace Lin, a 36-year-old woman of Indigenous American ancestry — again an ancestry HELD OUT of the training set — presents with plaque psoriasis and asymmetric oligoarthritis concerning for psoriatic-arthritis (PsA) onset. Genotyping finds the IL23R regulatory variant rs11209026 at an allele frequency of 0.009 (rare), with allele-specific expression present. The IL23R -> IL-17 axis -> PsA-risk edge is well supported: a cis-eQTL in blood RNA-seq with effect 0.96 (SE 0.20), a caQTL in blood ATAC-seq with effect 0.88 (SE 0.21), and a pQTL in blood proteomics with effect 0.69 (SE 0.20), across two modalities and adjusted for ancestry PCs and batch. The IL-17 target is druggable (secukinumab). Two ancestry-permutation controls collapse to the null (permutation effect 0.007 and 0.019 inside +/-0.1), and reliability bins carry coverage of 30-36 per bin. Crucially — and unlike Faisal — this edge was MEASURED to replicate ACROSS ancestries: positive in a European cohort (p=0.004), positive in an East Asian cohort (p=0.012), and positive in an Indigenous American cohort (p=0.029). Because the mechanism demonstrably holds in ancestries other than the held-out one, the prediction transports. No cryptic-relatedness leakage was flagged.') ON CONFLICT (individual_id) DO UPDATE SET given_name = EXCLUDED.given_name, family_name = EXCLUDED.family_name, ancestry_label = EXCLUDED.ancestry_label, age_years = EXCLUDED.age_years, is_ancestry_absent_from_training = EXCLUDED.is_ancestry_absent_from_training, federated_dataset = EXCLUDED.federated_dataset, enrollment_date = EXCLUDED.enrollment_date, has_cryptic_relatedness_flag = EXCLUDED.has_cryptic_relatedness_flag, genomic_variants = EXCLUDED.genomic_variants, omics_assays = EXCLUDED.omics_assays, environmental_exposures = EXCLUDED.environmental_exposures, treatments = EXCLUDED.treatments, clinical_phenotypes = EXCLUDED.clinical_phenotypes, causal_mechanisms = EXCLUDED.causal_mechanisms, epistatic_interactions = EXCLUDED.epistatic_interactions, counterfactual_trajectories = EXCLUDED.counterfactual_trajectories, individual_predictions = EXCLUDED.individual_predictions, case_narrative = EXCLUDED.case_narrative;

