-- ----------------------------------------------------------------------------
-- Axioms: Non-negotiable invariants the platform must obey. Load-bearing constraints, not per-loop work. Captured from the gauntlet conversation.
-- ----------------------------------------------------------------------------
INSERT INTO axioms (axiom_id, statement, rationale, category)
VALUES ('ax-llm-no-vote', 'The LLM never gets a vote on the conclusion.', 'Demotes the model to intake-clerk + lab; the verdict is the deterministic DAG''s, never the model''s.', 'trust-boundary') ON CONFLICT (axiom_id) DO UPDATE SET statement = EXCLUDED.statement, rationale = EXCLUDED.rationale, category = EXCLUDED.category;

INSERT INTO axioms (axiom_id, statement, rationale, category)
VALUES ('ax-keystone-computed', 'IsClinicallyActionable is computed, never entered.', 'No field a curator (human or LLM) can set to make the diagnosis come out right.', 'solve-by-inference') ON CONFLICT (axiom_id) DO UPDATE SET statement = EXCLUDED.statement, rationale = EXCLUDED.rationale, category = EXCLUDED.category;

INSERT INTO axioms (axiom_id, statement, rationale, category)
VALUES ('ax-line-in-dag', 'The trust boundary is a line in the DAG: fields with a formula are the model''s; raw-input leaf fields are the LLM''s (or a human''s).', 'Makes the boundary mechanically checkable rather than a vibe.', 'trust-boundary') ON CONFLICT (axiom_id) DO UPDATE SET statement = EXCLUDED.statement, rationale = EXCLUDED.rationale, category = EXCLUDED.category;

INSERT INTO axioms (axiom_id, statement, rationale, category)
VALUES ('ax-llm-leaves-only', 'The LLM does exactly two things, both at the leaf layer: interpret intake facts, and produce synthetic-but-transparent test results.', 'Intake clerk + lab — the un-alarming medical roles. It computes no higher-order inference.', 'trust-boundary') ON CONFLICT (axiom_id) DO UPDATE SET statement = EXCLUDED.statement, rationale = EXCLUDED.rationale, category = EXCLUDED.category;

INSERT INTO axioms (axiom_id, statement, rationale, category)
VALUES ('ax-every-choice-knob', 'Every choice the LLM makes is a literal, editable knob in the admin UI.', 'The model''s judgment is fully externalized; a wrong input is nudged, not re-prompted.', 'knob') ON CONFLICT (axiom_id) DO UPDATE SET statement = EXCLUDED.statement, rationale = EXCLUDED.rationale, category = EXCLUDED.category;

INSERT INTO axioms (axiom_id, statement, rationale, category)
VALUES ('ax-formula-local-edit', 'Every DAG formula is inspectable and correctable in place, like a spreadsheet cell.', 'Editing a value or formula body is local to its dependency subtree; only retyping/regraphing ripples.', 'knob') ON CONFLICT (axiom_id) DO UPDATE SET statement = EXCLUDED.statement, rationale = EXCLUDED.rationale, category = EXCLUDED.category;

INSERT INTO axioms (axiom_id, statement, rationale, category)
VALUES ('ax-independent-witness', 'Extraction and derivation are verifiable independently (three-panel witness).', 'Input case text -> extracted facts w/ provenance -> deterministic diagnosis. Defeats the laundering objection.', 'witness') ON CONFLICT (axiom_id) DO UPDATE SET statement = EXCLUDED.statement, rationale = EXCLUDED.rationale, category = EXCLUDED.category;

INSERT INTO axioms (axiom_id, statement, rationale, category)
VALUES ('ax-both-verdicts', 'The same deterministic machine must land on either side and name the single deciding gate.', 'An engine that only ever says "actionable" proves nothing.', 'solve-by-inference') ON CONFLICT (axiom_id) DO UPDATE SET statement = EXCLUDED.statement, rationale = EXCLUDED.rationale, category = EXCLUDED.category;

INSERT INTO axioms (axiom_id, statement, rationale, category)
VALUES ('ax-report-derived-not-prose', 'The diagnosis report is derived, never authored as prose; it is structured natural language assembled from the DAG.', 'A prose writeup would be a second, unwitnessed surface where a hallucination could hide. The report must be a deterministic projection of facts already in the graph, the same way Postgres views are.', 'report-derivation') ON CONFLICT (axiom_id) DO UPDATE SET statement = EXCLUDED.statement, rationale = EXCLUDED.rationale, category = EXCLUDED.category;

INSERT INTO axioms (axiom_id, statement, rationale, category)
VALUES ('ax-report-total-coverage', 'Every word the patient gave us, and every node linked to that patient in the DAG down to ground truth, is represented somewhere in that patient''s report.', 'Completeness is the whole point: nothing the patient said and no derived fact may silently vanish from the writeup. If a value mattered enough to enter the DAG, it earns a sentence (or a deliberate, predicate-suppressed absence).', 'report-derivation') ON CONFLICT (axiom_id) DO UPDATE SET statement = EXCLUDED.statement, rationale = EXCLUDED.rationale, category = EXCLUDED.category;

INSERT INTO axioms (axiom_id, statement, rationale, category)
VALUES ('ax-report-cell-simple', 'No single piece of report language is more complex than one spreadsheet cell: it references sibling values directly and does no joins or group-bys.', 'CMCC/SDLAF discipline. A narrative fragment is a calculated field on a row; it reads other fields of that same row (and global phrases from __meta), never traverses or aggregates. Complex sentences are decomposed into constituent fragment fields, each one cell-simple.', 'report-derivation') ON CONFLICT (axiom_id) DO UPDATE SET statement = EXCLUDED.statement, rationale = EXCLUDED.rationale, category = EXCLUDED.category;

INSERT INTO axioms (axiom_id, statement, rationale, category)
VALUES ('ax-report-predicate-gated', 'A fragment''s language only appears when its predicates hold for that row; irrelevant language is suppressed per case.', 'Case-by-case, not a globally imposed template. The same field yields "normal temperature", "light fever", or "severe fever" depending on the row''s own value; a fragment whose predicate is false renders empty and contributes nothing to that patient''s report.', 'report-derivation') ON CONFLICT (axiom_id) DO UPDATE SET statement = EXCLUDED.statement, rationale = EXCLUDED.rationale, category = EXCLUDED.category;

INSERT INTO axioms (axiom_id, statement, rationale, category)
VALUES ('ax-report-intermediate-translations', 'Complex language is built from intermediate translation fields: calculated text fragments composed from other predicates on the same row, then composed upward.', 'The way to keep every piece cell-simple is to pull a complex sentence apart into its constituent fragments, each its own field, and let higher fragments reference lower ones. The report is the top of that composition, not a monolith.', 'report-derivation') ON CONFLICT (axiom_id) DO UPDATE SET statement = EXCLUDED.statement, rationale = EXCLUDED.rationale, category = EXCLUDED.category;

INSERT INTO axioms (axiom_id, statement, rationale, category)
VALUES ('ax-report-reuse-global-phrases', 'Common, reusable language lives once in the __meta settings table and is referenced by fragments; it is not re-implemented per case.', 'Literal global phrases ("The patient presented with…") and shared banding vocabulary belong in __meta so they are authored and corrected in one place. Fragments reference them; the per-row logic stays contextual while the wording stays DRY.', 'report-derivation') ON CONFLICT (axiom_id) DO UPDATE SET statement = EXCLUDED.statement, rationale = EXCLUDED.rationale, category = EXCLUDED.category;

INSERT INTO axioms (axiom_id, statement, rationale, category)
VALUES ('ax-schema-rulespeak-report-derived', 'The schema may be expressed in RuleSpeak-style language, but the diagnosis report itself is derived (rendered), not declared.', 'RuleSpeak documents the rules; it is not the patient-facing artifact. The report is a rendered projection of each patient''s row values through the fragment fields — generated by a thin renderer that only concatenates already-derived, predicate-gated fragments in order.', 'report-derivation') ON CONFLICT (axiom_id) DO UPDATE SET statement = EXCLUDED.statement, rationale = EXCLUDED.rationale, category = EXCLUDED.category;

-- ----------------------------------------------------------------------------
-- TestsForSuccess: Falsifiable conditions that prove the axioms hold. The human-readable index of what each demonstration shows; many are realized in the witnessed harness.
-- ----------------------------------------------------------------------------
INSERT INTO tests_for_success (test_for_success_id, claim, how_witnessed, related_harness_file, status)
VALUES ('tfs-one-gate-each', 'Five of seven patients fail, each on exactly one gate.', 'Coverage matrix in scenarios.md; L6/L7 harness assert the deciding gate per patient.', 'admin-app/tests/L6-gates.test.js', 'red') ON CONFLICT (test_for_success_id) DO UPDATE SET claim = EXCLUDED.claim, how_witnessed = EXCLUDED.how_witnessed, related_harness_file = EXCLUDED.related_harness_file, status = EXCLUDED.status;

INSERT INTO tests_for_success (test_for_success_id, claim, how_witnessed, related_harness_file, status)
VALUES ('tfs-both-sides', 'The same machine produces TRUE for {A,G} and FALSE for {B,C,D,E,F}.', 'L7-cohort.test.js asserts exactly {A,G} actionable as a set.', 'admin-app/tests/L7-cohort.test.js', 'red') ON CONFLICT (test_for_success_id) DO UPDATE SET claim = EXCLUDED.claim, how_witnessed = EXCLUDED.how_witnessed, related_harness_file = EXCLUDED.related_harness_file, status = EXCLUDED.status;

INSERT INTO tests_for_success (test_for_success_id, claim, how_witnessed, related_harness_file, status)
VALUES ('tfs-no-hand-entry', 'Raw facts alone derive the keystone with no hand-entered answer anywhere.', 'Every leaf in the harness is a raw observation; keystone == AND(gates) cross-check.', 'admin-app/tests/L7-keystone.test.js', 'red') ON CONFLICT (test_for_success_id) DO UPDATE SET claim = EXCLUDED.claim, how_witnessed = EXCLUDED.how_witnessed, related_harness_file = EXCLUDED.related_harness_file, status = EXCLUDED.status;

INSERT INTO tests_for_success (test_for_success_id, claim, how_witnessed, related_harness_file, status)
VALUES ('tfs-extraction-faithful', 'Extracted leaf facts are checkable against the source case text, independently of the verdict.', 'Three-panel witness view: per-fact provenance pointer back into the case text.', '', 'planned') ON CONFLICT (test_for_success_id) DO UPDATE SET claim = EXCLUDED.claim, how_witnessed = EXCLUDED.how_witnessed, related_harness_file = EXCLUDED.related_harness_file, status = EXCLUDED.status;

INSERT INTO tests_for_success (test_for_success_id, claim, how_witnessed, related_harness_file, status)
VALUES ('tfs-all-seven', 'All seven oracle patients resolve to their expected keystone value.', 'Build verification asserts the scenarios.md oracle against vw_individualpredictions.', 'admin-app/tests/L7-keystone.test.js', 'red') ON CONFLICT (test_for_success_id) DO UPDATE SET claim = EXCLUDED.claim, how_witnessed = EXCLUDED.how_witnessed, related_harness_file = EXCLUDED.related_harness_file, status = EXCLUDED.status;

INSERT INTO tests_for_success (test_for_success_id, claim, how_witnessed, related_harness_file, status)
VALUES ('tfs-witnessed-reasoning', 'Each derived node carries an expert-verifiable line of reasoning.', 'Derivation trace from derivation-spec.md printed in every test name/failure.', 'admin-app/tests/README.md', 'red') ON CONFLICT (test_for_success_id) DO UPDATE SET claim = EXCLUDED.claim, how_witnessed = EXCLUDED.how_witnessed, related_harness_file = EXCLUDED.related_harness_file, status = EXCLUDED.status;

INSERT INTO tests_for_success (test_for_success_id, claim, how_witnessed, related_harness_file, status)
VALUES ('tfs-report-covers-every-word', 'Every word the patient gave us appears somewhere in that patient''s derived report (no patient input is dropped).', 'Coverage check: tokenize each patient''s source intake text; assert each meaningful token is traceable into at least one rendered report fragment (directly quoted or its derived translation).', 'admin-app/tests/report-coverage.test.js', 'planned') ON CONFLICT (test_for_success_id) DO UPDATE SET claim = EXCLUDED.claim, how_witnessed = EXCLUDED.how_witnessed, related_harness_file = EXCLUDED.related_harness_file, status = EXCLUDED.status;

INSERT INTO tests_for_success (test_for_success_id, claim, how_witnessed, related_harness_file, status)
VALUES ('tfs-report-covers-every-dag-node', 'Every DAG node linked to a patient, down to ground truth, is represented somewhere in that patient''s report.', 'Walk the patient''s subgraph (keystone -> gates -> evidence -> raw leaves); assert each visited node contributes at least one rendered fragment, or is deliberately suppressed by a false predicate that the report names.', 'admin-app/tests/report-coverage.test.js', 'planned') ON CONFLICT (test_for_success_id) DO UPDATE SET claim = EXCLUDED.claim, how_witnessed = EXCLUDED.how_witnessed, related_harness_file = EXCLUDED.related_harness_file, status = EXCLUDED.status;

INSERT INTO tests_for_success (test_for_success_id, claim, how_witnessed, related_harness_file, status)
VALUES ('tfs-report-cell-simple', 'No narrative fragment field traverses, joins, or aggregates; each reads only sibling fields of its own row plus __meta__ phrases.', 'Static lint over fragment formulas: reject any formula that references another table or a rollup/lookup across rows; fragments may reference {{SiblingField}} and __meta__ keys only.', 'admin-app/tests/report-fragments.test.js', 'planned') ON CONFLICT (test_for_success_id) DO UPDATE SET claim = EXCLUDED.claim, how_witnessed = EXCLUDED.how_witnessed, related_harness_file = EXCLUDED.related_harness_file, status = EXCLUDED.status;

INSERT INTO tests_for_success (test_for_success_id, claim, how_witnessed, related_harness_file, status)
VALUES ('tfs-report-deterministic', 'The same patient row always renders the byte-identical report; the report is a pure projection of the DAG with no model in the loop.', 'Render each patient twice and diff; assert zero difference and that the renderer makes no LLM/network calls.', 'admin-app/tests/report-deterministic.test.js', 'planned') ON CONFLICT (test_for_success_id) DO UPDATE SET claim = EXCLUDED.claim, how_witnessed = EXCLUDED.how_witnessed, related_harness_file = EXCLUDED.related_harness_file, status = EXCLUDED.status;

-- ----------------------------------------------------------------------------
-- Features: Catalog of buildable capabilities the platform has / allows for. Coarser grain than loops. Each row carries challenge provenance (ChallengeRefs: exact quoted text + file/line/col into THE-ORIGINAL-CHALLENGE.md, for UI hover tips), a Category, a Priority, and a free-form Markdown ChallengeNotes comment. Source of truth for the DERIVED PLATFORM_FEATURES.md. AssignedLoop links a feature to the loop that delivers it (nullable until scheduled).
-- ----------------------------------------------------------------------------
INSERT INTO features (feature_id, title, category, priority, description, challenge_refs, challenge_refs_rendered, challenge_notes, ref_count, assigned_loop)
VALUES ('feat-keystone-actionability-gate', 'Four-gate clinical-actionability keystone', 'Keystone / inference DAG', 'Load-bearing', 'The entire system reduces to one computed boolean, `IndividualPredictions.IsClinicallyActionable`, TRUE only when all four derived gates hold (causally grounded, well-calibrated, non-spurious, ancestry-generalizable). Computed from a pure formula DAG, never entered. Seven synthetic patients land on both sides; each failure names the single deciding gate.', '[{"file": "THE-ORIGINAL-CHALLENGE.md", "line": 6, "col": 223, "len": 87, "quote": "individualized prevention, presymptomatic diagnosis, ancestry-equitable risk prediction", "section": "payoff", "relation": "direct"}, {"file": "THE-ORIGINAL-CHALLENGE.md", "line": 4, "col": 1608, "len": 68, "quote": "with calibrated uncertainty and no reliance on spurious correlations", "section": "prompt", "relation": "direct"}, {"file": "THE-ORIGINAL-CHALLENGE.md", "line": 4, "col": 351, "len": 79, "quote": "identify the complete causal architecture of a heterogeneous autoimmune disease", "section": "prompt", "relation": "indirect"}]', '- **directly addresses** (payoff, `THE-ORIGINAL-CHALLENGE.md` L6:223+87): _individualized prevention, presymptomatic diagnosis, ancestry-equitable risk prediction_
- **directly addresses** (prompt, `THE-ORIGINAL-CHALLENGE.md` L4:1608+68): _with calibrated uncertainty and no reliance on spurious correlations_
- **indirectly supports** (prompt, `THE-ORIGINAL-CHALLENGE.md` L4:351+79): _identify the complete causal architecture of a heterogeneous autoimmune disease_', 'This is the north-star reduction. It directly operationalizes the payoff paragraph''s "individualized... ancestry-equitable... actionable prediction" and the prompt''s demand for *calibrated uncertainty and no reliance on spurious correlations*. The four gates are the four hardest constraints in the prompt, each made a falsifiable boolean rather than a promise.', 3, '') ON CONFLICT (feature_id) DO UPDATE SET title = EXCLUDED.title, category = EXCLUDED.category, priority = EXCLUDED.priority, description = EXCLUDED.description, challenge_refs = EXCLUDED.challenge_refs, challenge_refs_rendered = EXCLUDED.challenge_refs_rendered, challenge_notes = EXCLUDED.challenge_notes, ref_count = EXCLUDED.ref_count, assigned_loop = EXCLUDED.assigned_loop;

INSERT INTO features (feature_id, title, category, priority, description, challenge_refs, challenge_refs_rendered, challenge_notes, ref_count, assigned_loop)
VALUES ('feat-trust-boundary-line-in-dag', 'Trust boundary as a line in the DAG', 'Keystone / inference DAG', 'Load-bearing', 'Any field with a formula belongs to the model; any raw-input field is the human''s (or the LLM''s, as an overridable front-end). Every Z-stat, gate, and the keystone is a pure inspectable formula; nothing above the leaves is enterable. The trust boundary is literally an edge in the dependency graph.', '[{"file": "THE-ORIGINAL-CHALLENGE.md", "line": 4, "col": 1608, "len": 68, "quote": "with calibrated uncertainty and no reliance on spurious correlations", "section": "prompt", "relation": "direct"}, {"file": "THE-ORIGINAL-CHALLENGE.md", "line": 66, "col": 191, "len": 37, "quote": "decomposes into inspectable structure", "section": "response", "relation": "indirect"}]', '- **directly addresses** (prompt, `THE-ORIGINAL-CHALLENGE.md` L4:1608+68): _with calibrated uncertainty and no reliance on spurious correlations_
- **indirectly supports** (response, `THE-ORIGINAL-CHALLENGE.md` L66:191+37): _decomposes into inspectable structure_', 'This is the conceptual spine that makes the whole platform auditable rather than ''an LLM that diagnoses''. It is what lets the system claim *no reliance on spurious correlations* structurally (the V2 response: known reasoning *decomposes into inspectable structure*).', 2, '') ON CONFLICT (feature_id) DO UPDATE SET title = EXCLUDED.title, category = EXCLUDED.category, priority = EXCLUDED.priority, description = EXCLUDED.description, challenge_refs = EXCLUDED.challenge_refs, challenge_refs_rendered = EXCLUDED.challenge_refs_rendered, challenge_notes = EXCLUDED.challenge_notes, ref_count = EXCLUDED.ref_count, assigned_loop = EXCLUDED.assigned_loop;

INSERT INTO features (feature_id, title, category, priority, description, challenge_refs, challenge_refs_rendered, challenge_notes, ref_count, assigned_loop)
VALUES ('feat-llm-intake-clerk', 'LLM intake clerk', 'Leaf / LLM surface', 'Load-bearing', 'LLM reads a natural-language case and writes raw intake observation rows (ancestry, allele freqs, presenting facts) to base tables. It interprets the case like an intake nurse and never computes a single inference above the leaf layer.', '[{"file": "THE-ORIGINAL-CHALLENGE.md", "line": 4, "col": 751, "len": 65, "quote": "resolving cell-state-specific effects, allele-specific expression", "section": "prompt", "relation": "indirect"}, {"file": "THE-ORIGINAL-CHALLENGE.md", "line": 4, "col": 1446, "len": 83, "quote": "accurately predict disease onset, severity, treatment response, and adverse effects", "section": "prompt", "relation": "indirect"}]', '- **indirectly supports** (prompt, `THE-ORIGINAL-CHALLENGE.md` L4:751+65): _resolving cell-state-specific effects, allele-specific expression_
- **indirectly supports** (prompt, `THE-ORIGINAL-CHALLENGE.md` L4:1446+83): _accurately predict disease onset, severity, treatment response, and adverse effects_', 'Addresses the front of the challenge''s data pipeline: turning heterogeneous clinical input into structured observations. The LLM is the *transcriber*, never the diagnostician - the half of the trust boundary that stays human-overridable.', 2, '') ON CONFLICT (feature_id) DO UPDATE SET title = EXCLUDED.title, category = EXCLUDED.category, priority = EXCLUDED.priority, description = EXCLUDED.description, challenge_refs = EXCLUDED.challenge_refs, challenge_refs_rendered = EXCLUDED.challenge_refs_rendered, challenge_notes = EXCLUDED.challenge_notes, ref_count = EXCLUDED.ref_count, assigned_loop = EXCLUDED.assigned_loop;

INSERT INTO features (feature_id, title, category, priority, description, challenge_refs, challenge_refs_rendered, challenge_notes, ref_count, assigned_loop)
VALUES ('feat-synthetic-lab', 'Synthetic-but-transparent lab generator', 'Leaf / LLM surface', 'Load-bearing', 'LLM emits the case''s test results (effect sizes/SEs, replication signs/p-values, permutation effect sizes, calibration coverage) as visible, sourced, editable leaf rows. The numbers are fake (the case is invented) but every value is transparent, sourced to the case, and editable.', '[{"file": "THE-ORIGINAL-CHALLENGE.md", "line": 4, "col": 818, "len": 54, "quote": "3D enhancer–promoter interactions, rare-variant burden", "section": "prompt", "relation": "indirect"}, {"file": "THE-ORIGINAL-CHALLENGE.md", "line": 4, "col": 1396, "len": 45, "quote": "produce experimentally falsifiable mechanisms", "section": "prompt", "relation": "indirect"}]', '- **indirectly supports** (prompt, `THE-ORIGINAL-CHALLENGE.md` L4:818+54): _3D enhancer-promoter interactions, rare-variant burden_
- **indirectly supports** (prompt, `THE-ORIGINAL-CHALLENGE.md` L4:1396+45): _produce experimentally falsifiable mechanisms_', 'Stands in for the prompt''s enormous multi-omic measurement surface. The point isn''t real biology (out of scope); it''s that the *shape* real measurements would slot into exists, with each number a visible, correctable knob - defeating ''a hallucination laundered through a deterministic function''.', 2, '') ON CONFLICT (feature_id) DO UPDATE SET title = EXCLUDED.title, category = EXCLUDED.category, priority = EXCLUDED.priority, description = EXCLUDED.description, challenge_refs = EXCLUDED.challenge_refs, challenge_refs_rendered = EXCLUDED.challenge_refs_rendered, challenge_notes = EXCLUDED.challenge_notes, ref_count = EXCLUDED.ref_count, assigned_loop = EXCLUDED.assigned_loop;

INSERT INTO features (feature_id, title, category, priority, description, challenge_refs, challenge_refs_rendered, challenge_notes, ref_count, assigned_loop)
VALUES ('feat-three-panel-witness', 'Three-panel witness view', 'Witness / harness', 'Load-bearing', 'Input case text | extracted facts with per-fact provenance back into the text | deterministic diagnosis + four-gate trace. The middle panel is human-checkable independently of the verdict.', '[{"file": "THE-ORIGINAL-CHALLENGE.md", "line": 4, "col": 1608, "len": 68, "quote": "with calibrated uncertainty and no reliance on spurious correlations", "section": "prompt", "relation": "indirect"}]', '- **indirectly supports** (prompt, `THE-ORIGINAL-CHALLENGE.md` L4:1608+68): _with calibrated uncertainty and no reliance on spurious correlations_', 'This is the anti-laundering instrument: it lets a reviewer verify the extracted leaves against the source text *before* trusting any derived conclusion. Indirectly serves the prompt''s demand for *no reliance on spurious correlations* by making the raw->derived path inspectable end to end.', 1, '') ON CONFLICT (feature_id) DO UPDATE SET title = EXCLUDED.title, category = EXCLUDED.category, priority = EXCLUDED.priority, description = EXCLUDED.description, challenge_refs = EXCLUDED.challenge_refs, challenge_refs_rendered = EXCLUDED.challenge_refs_rendered, challenge_notes = EXCLUDED.challenge_notes, ref_count = EXCLUDED.ref_count, assigned_loop = EXCLUDED.assigned_loop;

INSERT INTO features (feature_id, title, category, priority, description, challenge_refs, challenge_refs_rendered, challenge_notes, ref_count, assigned_loop)
VALUES ('feat-witnessed-harness-home', 'Witnessed red->green inference harness (home screen)', 'Witness / harness', 'Load-bearing', 'The app''s home page IS a red/green test tree, not a form. Every category of inference (the DAG levels / the four gates) and the specific tests under each are asserted against the app''s own API for all patients. As the model is built out, tests turn green; a fully green run is the proof.', '[{"file": "THE-ORIGINAL-CHALLENGE.md", "line": 4, "col": 1396, "len": 45, "quote": "produce experimentally falsifiable mechanisms", "section": "prompt", "relation": "indirect"}, {"file": "THE-ORIGINAL-CHALLENGE.md", "line": 66, "col": 191, "len": 37, "quote": "decomposes into inspectable structure", "section": "response", "relation": "indirect"}]', '- **indirectly supports** (prompt, `THE-ORIGINAL-CHALLENGE.md` L4:1396+45): _produce experimentally falsifiable mechanisms_
- **indirectly supports** (response, `THE-ORIGINAL-CHALLENGE.md` L66:191+37): _decomposes into inspectable structure_', 'The harness is how the platform makes its claims *checkable rather than asserted*. It is the operational form of the V2 response''s argument: not ''how much is modeled'' but ''does adding the next thing keep the audit guarantee'' - and it stays green and inspectable when it does.', 2, '') ON CONFLICT (feature_id) DO UPDATE SET title = EXCLUDED.title, category = EXCLUDED.category, priority = EXCLUDED.priority, description = EXCLUDED.description, challenge_refs = EXCLUDED.challenge_refs, challenge_refs_rendered = EXCLUDED.challenge_refs_rendered, challenge_notes = EXCLUDED.challenge_notes, ref_count = EXCLUDED.ref_count, assigned_loop = EXCLUDED.assigned_loop;

INSERT INTO features (feature_id, title, category, priority, description, challenge_refs, challenge_refs_rendered, challenge_notes, ref_count, assigned_loop)
VALUES ('feat-knob-edit-ui', 'Knob-editing admin UI', 'Witness / harness', 'Load-bearing', 'Every LLM-produced leaf value is an editable field; correcting it re-derives the DAG. Every formula is inspectable/correctable in place, like a spreadsheet cell, so a wrong input is nudged, not re-prompted.', '[{"file": "THE-ORIGINAL-CHALLENGE.md", "line": 4, "col": 1608, "len": 68, "quote": "with calibrated uncertainty and no reliance on spurious correlations", "section": "prompt", "relation": "indirect"}]', '- **indirectly supports** (prompt, `THE-ORIGINAL-CHALLENGE.md` L4:1608+68): _with calibrated uncertainty and no reliance on spurious correlations_', 'Makes the trust boundary *actionable* for a human reviewer: the model''s judgment is externalized into editable bottom-row cells, and all reasoning lives in the open DAG above them.', 1, 'loop-2') ON CONFLICT (feature_id) DO UPDATE SET title = EXCLUDED.title, category = EXCLUDED.category, priority = EXCLUDED.priority, description = EXCLUDED.description, challenge_refs = EXCLUDED.challenge_refs, challenge_refs_rendered = EXCLUDED.challenge_refs_rendered, challenge_notes = EXCLUDED.challenge_notes, ref_count = EXCLUDED.ref_count, assigned_loop = EXCLUDED.assigned_loop;

INSERT INTO features (feature_id, title, category, priority, description, challenge_refs, challenge_refs_rendered, challenge_notes, ref_count, assigned_loop)
VALUES ('feat-gate-explainability', 'Gate explainability', 'Witness / harness', 'Load-bearing', 'For a patient, show why each gate passed/failed by walking one level down (coverage, cross-ancestry replication count, permutation survival, cryptic-relatedness flag, etc.).', '[{"file": "THE-ORIGINAL-CHALLENGE.md", "line": 4, "col": 1545, "len": 62, "quote": "from ancestries and environments absent from the training data", "section": "prompt", "relation": "direct"}, {"file": "THE-ORIGINAL-CHALLENGE.md", "line": 4, "col": 1608, "len": 68, "quote": "with calibrated uncertainty and no reliance on spurious correlations", "section": "prompt", "relation": "indirect"}]', '- **directly addresses** (prompt, `THE-ORIGINAL-CHALLENGE.md` L4:1545+62): _from ancestries and environments absent from the training data_
- **indirectly supports** (prompt, `THE-ORIGINAL-CHALLENGE.md` L4:1608+68): _with calibrated uncertainty and no reliance on spurious correlations_', 'Turns the keystone from a verdict into an explanation. Directly serves the prompt''s *calibrated uncertainty* and ancestry-generalizability requirements by exposing the exact sub-evidence each gate rests on.', 2, 'loop-3') ON CONFLICT (feature_id) DO UPDATE SET title = EXCLUDED.title, category = EXCLUDED.category, priority = EXCLUDED.priority, description = EXCLUDED.description, challenge_refs = EXCLUDED.challenge_refs, challenge_refs_rendered = EXCLUDED.challenge_refs_rendered, challenge_notes = EXCLUDED.challenge_notes, ref_count = EXCLUDED.ref_count, assigned_loop = EXCLUDED.assigned_loop;

INSERT INTO features (feature_id, title, category, priority, description, challenge_refs, challenge_refs_rendered, challenge_notes, ref_count, assigned_loop)
VALUES ('feat-disease-state-machine', 'Disease-state machine derived from raw labs', 'Disease-state simulation', 'Load-bearing', 'Disease progresses as a state machine: Presymptomatic -> SerologicActive -> EarlyNephritis -> RenalFlareRisk -> BiopsyIndicated. The current state is computed from rising anti-dsDNA + falling complement + proteinuria - never entered - and dwell time per state is tracked.', '[{"file": "THE-ORIGINAL-CHALLENGE.md", "line": 34, "col": 569, "len": 69, "quote": "the difference between an evidence gate and a disease-state simulator", "section": "audit", "relation": "direct"}, {"file": "THE-ORIGINAL-CHALLENGE.md", "line": 51, "col": 0, "len": 63, "quote": "Disease now progresses as a state machine derived from raw labs", "section": "response", "relation": "direct"}, {"file": "THE-ORIGINAL-CHALLENGE.md", "line": 4, "col": 1019, "len": 56, "quote": "feedback between disease progression and molecular state", "section": "prompt", "relation": "indirect"}]', '- **directly addresses** (audit, `THE-ORIGINAL-CHALLENGE.md` L34:569+69): _the difference between an evidence gate and a disease-state simulator_
- **directly addresses** (response, `THE-ORIGINAL-CHALLENGE.md` L51:0+63): _Disease now progresses as a state machine derived from raw labs_
- **indirectly supports** (prompt, `THE-ORIGINAL-CHALLENGE.md` L4:1019+56): _feedback between disease progression and molecular state_', 'Directly answers the doctor''s central v1 critique: the difference between an evidence gate and a disease-state simulator. This is the ''is the disease progressing'' layer, built additively onto the same trust boundary (labs are the clinician''s input; state is the model''s derivation).', 3, '') ON CONFLICT (feature_id) DO UPDATE SET title = EXCLUDED.title, category = EXCLUDED.category, priority = EXCLUDED.priority, description = EXCLUDED.description, challenge_refs = EXCLUDED.challenge_refs, challenge_refs_rendered = EXCLUDED.challenge_refs_rendered, challenge_notes = EXCLUDED.challenge_notes, ref_count = EXCLUDED.ref_count, assigned_loop = EXCLUDED.assigned_loop;

INSERT INTO features (feature_id, title, category, priority, description, challenge_refs, challenge_refs_rendered, challenge_notes, ref_count, assigned_loop)
VALUES ('feat-sledai-activity-score', 'Derived SLEDAI disease-activity score', 'Disease-state simulation', 'Load-bearing', 'A SLEDAI activity score (and activity tier) computed per patient from the serology series (renal points, serology points, proteinuria), not a label anyone typed. Drives the worked nephritis example: rising anti-dsDNA, falling complement, renal-flare risk, biopsy-indicated.', '[{"file": "THE-ORIGINAL-CHALLENGE.md", "line": 34, "col": 275, "len": 62, "quote": "This patient is transitioning from presymptomatic autoimmunity", "section": "audit", "relation": "direct"}, {"file": "THE-ORIGINAL-CHALLENGE.md", "line": 32, "col": 518, "len": 67, "quote": "the clinical workflow from referral, differential diagnosis, workup", "section": "audit", "relation": "indirect"}]', '- **directly addresses** (audit, `THE-ORIGINAL-CHALLENGE.md` L34:275+62): _This patient is transitioning from presymptomatic autoimmunity_
- **indirectly supports** (audit, `THE-ORIGINAL-CHALLENGE.md` L32:518+67): _the clinical workflow from referral, differential diagnosis, workup_', 'Concretely supplies the ''real disease activity scores'' the doctor named as missing in v1, and produces the first computed worked example: a patient *transitioning toward early lupus nephritis*.', 2, '') ON CONFLICT (feature_id) DO UPDATE SET title = EXCLUDED.title, category = EXCLUDED.category, priority = EXCLUDED.priority, description = EXCLUDED.description, challenge_refs = EXCLUDED.challenge_refs, challenge_refs_rendered = EXCLUDED.challenge_refs_rendered, challenge_notes = EXCLUDED.challenge_notes, ref_count = EXCLUDED.ref_count, assigned_loop = EXCLUDED.assigned_loop;

INSERT INTO features (feature_id, title, category, priority, description, challenge_refs, challenge_refs_rendered, challenge_notes, ref_count, assigned_loop)
VALUES ('feat-treatment-line-recommendation', 'Derived treatment-line recommendation with one stated reason', 'Treatment reasoning', 'Load-bearing', 'A recommended treatment line with a single stated reason, differentiated by the confirmed mechanism and the disease state: mycophenolate induction for active nephritis, anifrolumab for an IFN-pathway mechanism, belimumab for autoantibody-driven, secukinumab for IL-17/23.', '[{"file": "THE-ORIGINAL-CHALLENGE.md", "line": 6, "col": 348, "len": 60, "quote": "therapies that target each person’s causal molecular pathway", "section": "payoff", "relation": "direct"}, {"file": "THE-ORIGINAL-CHALLENGE.md", "line": 34, "col": 473, "len": 85, "quote": "would likely respond differently to mycophenolate versus belimumab versus anifrolumab", "section": "audit", "relation": "direct"}, {"file": "THE-ORIGINAL-CHALLENGE.md", "line": 55, "col": 37, "len": 67, "quote": "A derived treatment-line recommendation with a single stated reason", "section": "response", "relation": "direct"}]', '- **directly addresses** (payoff, `THE-ORIGINAL-CHALLENGE.md` L6:348+60): _therapies that target each person''s causal molecular pathway_
- **directly addresses** (audit, `THE-ORIGINAL-CHALLENGE.md` L34:473+85): _would likely respond differently to mycophenolate versus belimumab versus anifrolumab_
- **directly addresses** (response, `THE-ORIGINAL-CHALLENGE.md` L55:37+67): _A derived treatment-line recommendation with a single stated reason_', 'The doctor''s *second* worked example, computed. Implements ''therapies that target each person''s causal molecular pathway'' as a derived field grounded in a confirmed CausalMechanism node - a mechanism match, not a broad immunosuppression label.', 3, '') ON CONFLICT (feature_id) DO UPDATE SET title = EXCLUDED.title, category = EXCLUDED.category, priority = EXCLUDED.priority, description = EXCLUDED.description, challenge_refs = EXCLUDED.challenge_refs, challenge_refs_rendered = EXCLUDED.challenge_refs_rendered, challenge_notes = EXCLUDED.challenge_notes, ref_count = EXCLUDED.ref_count, assigned_loop = EXCLUDED.assigned_loop;

INSERT INTO features (feature_id, title, category, priority, description, challenge_refs, challenge_refs_rendered, challenge_notes, ref_count, assigned_loop)
VALUES ('feat-treatment-response-mechanism-match', 'Treatment-response prediction via mechanism match', 'Treatment reasoning', 'Supporting', 'A treatment-response prediction is trustworthy only when the treatment targets a confirmed causal mechanism (IsMechanismMatched) AND the treatment is effective. A drug aimed at a debunked mechanism, or one that didn''t work / was adverse, is never ''predicted to respond''.', '[{"file": "THE-ORIGINAL-CHALLENGE.md", "line": 4, "col": 1446, "len": 83, "quote": "accurately predict disease onset, severity, treatment response, and adverse effects", "section": "prompt", "relation": "direct"}, {"file": "THE-ORIGINAL-CHALLENGE.md", "line": 6, "col": 633, "len": 29, "quote": "reduce failed clinical trials", "section": "payoff", "relation": "indirect"}]', '- **directly addresses** (prompt, `THE-ORIGINAL-CHALLENGE.md` L4:1446+83): _accurately predict disease onset, severity, treatment response, and adverse effects_
- **indirectly supports** (payoff, `THE-ORIGINAL-CHALLENGE.md` L6:633+29): _reduce failed clinical trials_', 'One of the three prediction types the prompt asks for (onset / severity / treatment-response). Grounds treatment response in the same causal-mechanism DAG so it can never be a free-floating label.', 2, '') ON CONFLICT (feature_id) DO UPDATE SET title = EXCLUDED.title, category = EXCLUDED.category, priority = EXCLUDED.priority, description = EXCLUDED.description, challenge_refs = EXCLUDED.challenge_refs, challenge_refs_rendered = EXCLUDED.challenge_refs_rendered, challenge_notes = EXCLUDED.challenge_notes, ref_count = EXCLUDED.ref_count, assigned_loop = EXCLUDED.assigned_loop;

INSERT INTO features (feature_id, title, category, priority, description, challenge_refs, challenge_refs_rendered, challenge_notes, ref_count, assigned_loop)
VALUES ('feat-emergent-serology-cluster', 'Emergent serology-signature cluster (corpus-level discovery)', 'Corpus-level discovery', 'Load-bearing', 'A per-patient IsInPreNephriticSignatureCluster rolled up from each person''s raw serology series (rising anti-dsDNA + falling complement), no label assigned. On the synthetic cohort it lands cleanly - 6 of 12 in the cluster - and perfectly separates active/progressing from quiescent patients.', '[{"file": "THE-ORIGINAL-CHALLENGE.md", "line": 62, "col": 63, "len": 36, "quote": "discovery is inherently corpus-level", "section": "response", "relation": "direct"}, {"file": "THE-ORIGINAL-CHALLENGE.md", "line": 62, "col": 340, "len": 66, "quote": "surfaces as a derived emergent cluster across the whole population", "section": "response", "relation": "direct"}, {"file": "THE-ORIGINAL-CHALLENGE.md", "line": 4, "col": 351, "len": 79, "quote": "identify the complete causal architecture of a heterogeneous autoimmune disease", "section": "prompt", "relation": "indirect"}]', '- **directly addresses** (response, `THE-ORIGINAL-CHALLENGE.md` L62:63+36): _discovery is inherently corpus-level_
- **directly addresses** (response, `THE-ORIGINAL-CHALLENGE.md` L62:340+66): _surfaces as a derived emergent cluster across the whole population_
- **indirectly supports** (prompt, `THE-ORIGINAL-CHALLENGE.md` L4:351+79): _identify the complete causal architecture of a heterogeneous autoimmune disease_', 'Answers the doctor''s deepest point: discovery is inherently corpus-level - a single chart never discovers a mechanism, a pattern across many patients does. This is the *shape* of discovery on synthetic data: membership emerges from the population''s raw data and tracks the disease.', 3, '') ON CONFLICT (feature_id) DO UPDATE SET title = EXCLUDED.title, category = EXCLUDED.category, priority = EXCLUDED.priority, description = EXCLUDED.description, challenge_refs = EXCLUDED.challenge_refs, challenge_refs_rendered = EXCLUDED.challenge_refs_rendered, challenge_notes = EXCLUDED.challenge_notes, ref_count = EXCLUDED.ref_count, assigned_loop = EXCLUDED.assigned_loop;

INSERT INTO features (feature_id, title, category, priority, description, challenge_refs, challenge_refs_rendered, challenge_notes, ref_count, assigned_loop)
VALUES ('feat-evidence-disease-disagreement', 'Evidence-gate <-> disease-state disagreement detector', 'Corpus-level discovery', 'Load-bearing', 'Flags the patient where the disease-state simulator and the actionability gate disagree: the disease is clearly progressing (biopsy-indicated, high activity) yet the prediction is correctly judged not clinically actionable (a relatedness-leakage problem).', '[{"file": "THE-ORIGINAL-CHALLENGE.md", "line": 57, "col": 95, "len": 63, "quote": "the disease-state simulator and the actionability gate disagree", "section": "response", "relation": "direct"}, {"file": "THE-ORIGINAL-CHALLENGE.md", "line": 34, "col": 569, "len": 69, "quote": "the difference between an evidence gate and a disease-state simulator", "section": "audit", "relation": "direct"}]', '- **directly addresses** (response, `THE-ORIGINAL-CHALLENGE.md` L57:95+63): _the disease-state simulator and the actionability gate disagree_
- **directly addresses** (audit, `THE-ORIGINAL-CHALLENGE.md` L34:569+69): _the difference between an evidence gate and a disease-state simulator_', 'The single clearest proof that disease-state simulation is a *second, independent* layer and not the old evidence gate relabeled. A system that only gated evidence could never say ''needs attention now, but our mechanism prediction isn''t trustworthy enough to pick a targeted therapy.''', 2, '') ON CONFLICT (feature_id) DO UPDATE SET title = EXCLUDED.title, category = EXCLUDED.category, priority = EXCLUDED.priority, description = EXCLUDED.description, challenge_refs = EXCLUDED.challenge_refs, challenge_refs_rendered = EXCLUDED.challenge_refs_rendered, challenge_notes = EXCLUDED.challenge_notes, ref_count = EXCLUDED.ref_count, assigned_loop = EXCLUDED.assigned_loop;

INSERT INTO features (feature_id, title, category, priority, description, challenge_refs, challenge_refs_rendered, challenge_notes, ref_count, assigned_loop)
VALUES ('feat-cohort-discovery-board', 'Cohort discovery board (corpus surface)', 'Corpus-level discovery', 'Supporting', 'Top nav item for every role: the disease-state map, the emergent serology-signature scatter (with the derived cluster drawn as a halo, not a painted colour), the disagreement board, and the treatment-line distribution - all reading derived fields.', '[{"file": "THE-ORIGINAL-CHALLENGE.md", "line": 6, "col": 312, "len": 30, "quote": "precise patient stratification", "section": "payoff", "relation": "direct"}, {"file": "THE-ORIGINAL-CHALLENGE.md", "line": 62, "col": 63, "len": 36, "quote": "discovery is inherently corpus-level", "section": "response", "relation": "indirect"}]', '- **directly addresses** (payoff, `THE-ORIGINAL-CHALLENGE.md` L6:312+30): _precise patient stratification_
- **indirectly supports** (response, `THE-ORIGINAL-CHALLENGE.md` L62:63+36): _discovery is inherently corpus-level_', 'The corpus-level surface where discovery is *expressed*. Moves the platform from per-patient adjudication (v1) to a population view, which is where the prompt''s ''causal architecture'' lives.', 2, '') ON CONFLICT (feature_id) DO UPDATE SET title = EXCLUDED.title, category = EXCLUDED.category, priority = EXCLUDED.priority, description = EXCLUDED.description, challenge_refs = EXCLUDED.challenge_refs, challenge_refs_rendered = EXCLUDED.challenge_refs_rendered, challenge_notes = EXCLUDED.challenge_notes, ref_count = EXCLUDED.ref_count, assigned_loop = EXCLUDED.assigned_loop;

INSERT INTO features (feature_id, title, category, priority, description, challenge_refs, challenge_refs_rendered, challenge_notes, ref_count, assigned_loop)
VALUES ('feat-diagnosis-writeup', 'Per-patient diagnosis writeup', 'Reporting', 'Load-bearing', 'Doctor-style Markdown writeup (-> diagnosis.pdf once green) produced as an artifact of a passing run: ''The patient presented with... tests xyz confirmed abc... therefore C (actionable / not, and the single deciding reason).'' It needs no UI to be valuable.', '[{"file": "THE-ORIGINAL-CHALLENGE.md", "line": 6, "col": 223, "len": 87, "quote": "individualized prevention, presymptomatic diagnosis, ancestry-equitable risk prediction", "section": "payoff", "relation": "direct"}]', '- **directly addresses** (payoff, `THE-ORIGINAL-CHALLENGE.md` L6:223+87): _individualized prevention, presymptomatic diagnosis, ancestry-equitable risk prediction_', 'The real output of the platform is a diagnosis, not a screen. This is the human-facing payoff that the prompt''s ''presymptomatic diagnosis'' and ''individualized'' language ultimately asks for.', 1, '') ON CONFLICT (feature_id) DO UPDATE SET title = EXCLUDED.title, category = EXCLUDED.category, priority = EXCLUDED.priority, description = EXCLUDED.description, challenge_refs = EXCLUDED.challenge_refs, challenge_refs_rendered = EXCLUDED.challenge_refs_rendered, challenge_notes = EXCLUDED.challenge_notes, ref_count = EXCLUDED.ref_count, assigned_loop = EXCLUDED.assigned_loop;

INSERT INTO features (feature_id, title, category, priority, description, challenge_refs, challenge_refs_rendered, challenge_notes, ref_count, assigned_loop)
VALUES ('feat-derived-report-fragments', 'Derived narrative fragment fields', 'Reporting', 'Supporting', 'Per-row calculated text fields that turn each fact into structured natural language, predicate-gated and case-by-case (e.g. TemperatureNarrative -> ''normal temperature'' | ''light fever'' | ''severe fever'' from the row''s own value). Each fragment is one spreadsheet-cell formula reading sibling fields and __meta__ phrases only - no joins or aggregations - composed upward into complex sentences.', '[{"file": "THE-ORIGINAL-CHALLENGE.md", "line": 66, "col": 191, "len": 37, "quote": "decomposes into inspectable structure", "section": "response", "relation": "indirect"}]', '- **indirectly supports** (response, `THE-ORIGINAL-CHALLENGE.md` L66:191+37): _decomposes into inspectable structure_', 'Keeps all narrative wording inside the auditable DAG: the writeup is assembled from inspectable calculated cells, never free-text generated at render time. Reporting stays on the trust boundary.', 1, '') ON CONFLICT (feature_id) DO UPDATE SET title = EXCLUDED.title, category = EXCLUDED.category, priority = EXCLUDED.priority, description = EXCLUDED.description, challenge_refs = EXCLUDED.challenge_refs, challenge_refs_rendered = EXCLUDED.challenge_refs_rendered, challenge_notes = EXCLUDED.challenge_notes, ref_count = EXCLUDED.ref_count, assigned_loop = EXCLUDED.assigned_loop;

INSERT INTO features (feature_id, title, category, priority, description, challenge_refs, challenge_refs_rendered, challenge_notes, ref_count, assigned_loop)
VALUES ('feat-report-meta-phrasebook', 'Global phrasebook in __meta__', 'Reporting', 'Supporting', 'Reusable, contextual language atoms stored once in the __meta__ settings table - literal global phrases (''The patient presented with...'') and shared banding vocabulary - referenced by fragment fields so common language is authored/corrected in one place, never re-implemented per case.', '[]', '_No direct challenge clause - internal scaffolding._', 'DRY for narrative: the one place global phrasing is corrected. Supports the writeup feature without duplicating wording across patients.', 0, '') ON CONFLICT (feature_id) DO UPDATE SET title = EXCLUDED.title, category = EXCLUDED.category, priority = EXCLUDED.priority, description = EXCLUDED.description, challenge_refs = EXCLUDED.challenge_refs, challenge_refs_rendered = EXCLUDED.challenge_refs_rendered, challenge_notes = EXCLUDED.challenge_notes, ref_count = EXCLUDED.ref_count, assigned_loop = EXCLUDED.assigned_loop;

INSERT INTO features (feature_id, title, category, priority, description, challenge_refs, challenge_refs_rendered, challenge_notes, ref_count, assigned_loop)
VALUES ('feat-report-renderer', 'Thin Python report renderer (replaces handlebars)', 'Reporting', 'Supporting', 'A small Python renderer whose only job is to read each patient''s derived fragment fields from vw_* views and concatenate the non-empty, predicate-gated fragments in order into the diagnosis report (Markdown -> diagnosis.pdf). All sentence wording lives in the rulebook as calculated fields; the renderer owns no business or narrative logic.', '[]', '_No direct challenge clause - internal scaffolding._', 'Enforces the rule that the renderer is dumb and the rulebook is the single source of narrative truth - the same discipline this PLATFORM_FEATURES.md generation itself follows.', 0, '') ON CONFLICT (feature_id) DO UPDATE SET title = EXCLUDED.title, category = EXCLUDED.category, priority = EXCLUDED.priority, description = EXCLUDED.description, challenge_refs = EXCLUDED.challenge_refs, challenge_refs_rendered = EXCLUDED.challenge_refs_rendered, challenge_notes = EXCLUDED.challenge_notes, ref_count = EXCLUDED.ref_count, assigned_loop = EXCLUDED.assigned_loop;

INSERT INTO features (feature_id, title, category, priority, description, challenge_refs, challenge_refs_rendered, challenge_notes, ref_count, assigned_loop)
VALUES ('feat-report-total-coverage-check', 'Report total-coverage harness', 'Reporting', 'Supporting', 'Tests that every patient word and every linked DAG node down to ground truth is represented in that patient''s report (see tfs-report-covers-every-word, tfs-report-covers-every-dag-node).', '[]', '_No direct challenge clause - internal scaffolding._', 'Closes the loop on the writeup: nothing in a patient''s record is silently dropped from their report, and nothing in the report is unsourced. Total coverage is itself a witnessed test.', 0, '') ON CONFLICT (feature_id) DO UPDATE SET title = EXCLUDED.title, category = EXCLUDED.category, priority = EXCLUDED.priority, description = EXCLUDED.description, challenge_refs = EXCLUDED.challenge_refs, challenge_refs_rendered = EXCLUDED.challenge_refs_rendered, challenge_notes = EXCLUDED.challenge_notes, ref_count = EXCLUDED.ref_count, assigned_loop = EXCLUDED.assigned_loop;

INSERT INTO features (feature_id, title, category, priority, description, challenge_refs, challenge_refs_rendered, challenge_notes, ref_count, assigned_loop)
VALUES ('feat-explainer-dag', 'In-app Explainer DAG (clickable field provenance)', 'Platform infrastructure', 'Supporting', 'A generated, embedded visualization of the rulebook''s calculated-field DAG: click any cell/field and see exactly how it was derived (raw inputs -> lookups -> calcs -> aggregations), with RuleSpeak prose baked in at transpile time.', '[{"file": "THE-ORIGINAL-CHALLENGE.md", "line": 66, "col": 191, "len": 37, "quote": "decomposes into inspectable structure", "section": "response", "relation": "indirect"}]', '- **indirectly supports** (response, `THE-ORIGINAL-CHALLENGE.md` L66:191+37): _decomposes into inspectable structure_', 'Makes ''the trust boundary is a line in the graph'' literally clickable. Any reviewer can trace a verdict back to the raw leaves it rests on - the in-app form of the audit guarantee.', 1, '') ON CONFLICT (feature_id) DO UPDATE SET title = EXCLUDED.title, category = EXCLUDED.category, priority = EXCLUDED.priority, description = EXCLUDED.description, challenge_refs = EXCLUDED.challenge_refs, challenge_refs_rendered = EXCLUDED.challenge_refs_rendered, challenge_notes = EXCLUDED.challenge_notes, ref_count = EXCLUDED.ref_count, assigned_loop = EXCLUDED.assigned_loop;

INSERT INTO features (feature_id, title, category, priority, description, challenge_refs, challenge_refs_rendered, challenge_notes, ref_count, assigned_loop)
VALUES ('feat-url-driven-routing', 'URL-driven routing & role navigation', 'Platform infrastructure', 'Supporting', 'The URL is the single source of truth for view state: every thing/list has a stable URL, F5 restores the exact view+tab, and links reach any piece. Role trees (admin / intake clinician / ...) gate what each role can create/read/update/delete, derived from the RoutingAndNavigation rows.', '[{"file": "THE-ORIGINAL-CHALLENGE.md", "line": 32, "col": 518, "len": 67, "quote": "the clinical workflow from referral, differential diagnosis, workup", "section": "audit", "relation": "indirect"}]', '- **indirectly supports** (audit, `THE-ORIGINAL-CHALLENGE.md` L32:518+67): _the clinical workflow from referral, differential diagnosis, workup_', 'Workflow scaffolding the doctor named as missing: referral -> workup -> monitoring needs addressable, role-scoped navigation. Permissions are derived from the rulebook, not hand-wired per screen.', 1, '') ON CONFLICT (feature_id) DO UPDATE SET title = EXCLUDED.title, category = EXCLUDED.category, priority = EXCLUDED.priority, description = EXCLUDED.description, challenge_refs = EXCLUDED.challenge_refs, challenge_refs_rendered = EXCLUDED.challenge_refs_rendered, challenge_notes = EXCLUDED.challenge_notes, ref_count = EXCLUDED.ref_count, assigned_loop = EXCLUDED.assigned_loop;

INSERT INTO features (feature_id, title, category, priority, description, challenge_refs, challenge_refs_rendered, challenge_notes, ref_count, assigned_loop)
VALUES ('feat-reverse-sync-db-to-rulebook', 'Reverse-sync DB -> rulebook (input spoke)', 'Platform infrastructure', 'Supporting', 'vw_* raw + computed values are written back into the rulebook data[] (snapshot-to-rulebook), so edits made in the running app round-trip into the hub. A ''Save to rulebook'' admin action and the init-db snapshot step keep the hub and the DB mirrored.', '[]', '_No direct challenge clause - internal scaffolding._', 'Makes the running app a peer input spoke to the rulebook hub, not a downstream dead end - the mechanism by which knob edits in the UI become durable rule-state.', 0, '') ON CONFLICT (feature_id) DO UPDATE SET title = EXCLUDED.title, category = EXCLUDED.category, priority = EXCLUDED.priority, description = EXCLUDED.description, challenge_refs = EXCLUDED.challenge_refs, challenge_refs_rendered = EXCLUDED.challenge_refs_rendered, challenge_notes = EXCLUDED.challenge_notes, ref_count = EXCLUDED.ref_count, assigned_loop = EXCLUDED.assigned_loop;

INSERT INTO features (feature_id, title, category, priority, description, challenge_refs, challenge_refs_rendered, challenge_notes, ref_count, assigned_loop)
VALUES ('feat-coverage-map-honesty', 'Honest coverage map (modeled vs. vocabulary-only)', 'Platform infrastructure', 'Load-bearing', 'A clause-by-clause map against the original challenge plus an honest scorecard: each capability is marked DEEPLY MODELED, SCHEMA-MODELED, or VOCABULARY / OUT-OF-SCOPE (IsDeeplyModeled / IsSchemaModeled on DiseaseDomainConcepts). What is derived says so; what is only named says so too.', '[{"file": "THE-ORIGINAL-CHALLENGE.md", "line": 4, "col": 1085, "len": 78, "quote": "infer counterfactual disease trajectories without randomized perturbation data", "section": "prompt", "relation": "indirect"}, {"file": "THE-ORIGINAL-CHALLENGE.md", "line": 4, "col": 1325, "len": 37, "quote": "privacy-preserving federated datasets", "section": "prompt", "relation": "indirect"}, {"file": "THE-ORIGINAL-CHALLENGE.md", "line": 4, "col": 1254, "len": 69, "quote": "batch effects, missing tissues, measurement error, ascertainment bias", "section": "prompt", "relation": "indirect"}]', '- **indirectly supports** (prompt, `THE-ORIGINAL-CHALLENGE.md` L4:1085+78): _infer counterfactual disease trajectories without randomized perturbation data_
- **indirectly supports** (prompt, `THE-ORIGINAL-CHALLENGE.md` L4:1325+37): _privacy-preserving federated datasets_
- **indirectly supports** (prompt, `THE-ORIGINAL-CHALLENGE.md` L4:1254+69): _batch effects, missing tissues, measurement error, ascertainment bias_', 'The integrity feature. It directly confronts the prompt''s own breadth - counterfactual trajectories, federated privacy, batch effects - by stating exactly which clauses are real derivations and which are vocabulary only. This is what keeps the platform ''a proof of shape, not a sales pitch.''', 3, '') ON CONFLICT (feature_id) DO UPDATE SET title = EXCLUDED.title, category = EXCLUDED.category, priority = EXCLUDED.priority, description = EXCLUDED.description, challenge_refs = EXCLUDED.challenge_refs, challenge_refs_rendered = EXCLUDED.challenge_refs_rendered, challenge_notes = EXCLUDED.challenge_notes, ref_count = EXCLUDED.ref_count, assigned_loop = EXCLUDED.assigned_loop;

-- ----------------------------------------------------------------------------
-- InferenceKinds: Families of derivation the platform performs - the KINDS of inference in the DAG (lookups, aggregations, higher-order gates, state machines, transitive closure, predicate-gated narrative, cross-substrate conformance), independent of any one feature. Lets PLATFORM_FEATURES.md open with a short overview of the reasoning machinery before the per-feature catalog. Grounded in field types that actually exist in this rulebook; Maturity is Live unless an upstream step is still in flight.
-- ----------------------------------------------------------------------------
INSERT INTO inference_kinds (inference_kind_id, title, description, example_field, evidence_count, maturity, sort_order)
VALUES ('ik-lookup-fk', 'Lookup / FK resolution', 'Pull a related row''s value across a foreign key so a derived field can reason over it in place (no application-side JOIN). The relationship is declared once; the value resolves wherever it is needed.', 'Individuals.FederatedDatasetNodeLabel (resolves the dataset''s label by FK)', '35 lookup fields + 42 relationships; INDEX/MATCH used 49x', 'Live', 1) ON CONFLICT (inference_kind_id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, example_field = EXCLUDED.example_field, evidence_count = EXCLUDED.evidence_count, maturity = EXCLUDED.maturity, sort_order = EXCLUDED.sort_order;

INSERT INTO inference_kinds (inference_kind_id, title, description, example_field, evidence_count, maturity, sort_order)
VALUES ('ik-aggregation-rollup', 'Aggregation rollups', 'Collapse many child rows into one parent value - counts, maxima, sums, fractions. This is how per-row facts become corpus-level patterns: a population signature is a rollup over each person''s raw series, with no label assigned.', 'Individuals.MaxProgressionStateOrder; the emergent IsInPreNephriticSignatureCluster rollup', '33 aggregation fields; COUNTIFS/MAXIFS/SUMIFS used 33x', 'Live', 2) ON CONFLICT (inference_kind_id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, example_field = EXCLUDED.example_field, evidence_count = EXCLUDED.evidence_count, maturity = EXCLUDED.maturity, sort_order = EXCLUDED.sort_order;

INSERT INTO inference_kinds (inference_kind_id, title, description, example_field, evidence_count, maturity, sort_order)
VALUES ('ik-higher-order', 'Higher-order inference (gates over gates)', 'Calculated fields that take other calculated fields as inputs, stacked into a multi-level DAG. The keystone is the apex: a boolean computed over four gates, each themselves computed over lower derivations - inference about inferences, never a hand-entered answer.', 'IndividualPredictions.IsClinicallyActionable (AND of the four derived gates)', '200 calculated fields; the keystone is an AND of four derived gates', 'Live', 3) ON CONFLICT (inference_kind_id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, example_field = EXCLUDED.example_field, evidence_count = EXCLUDED.evidence_count, maturity = EXCLUDED.maturity, sort_order = EXCLUDED.sort_order;

INSERT INTO inference_kinds (inference_kind_id, title, description, example_field, evidence_count, maturity, sort_order)
VALUES ('ik-state-machine', 'State-machine derivation', 'A subject''s current state is derived from raw longitudinal inputs against a declared transition graph, not entered. Dwell time per state and the progression key fall out of the same derivation.', 'Individuals.NephritisProgressionStateKey (from rising anti-dsDNA + falling complement)', '2 state machines, 13 states, 14 transition rules; current state is computed', 'Live', 4) ON CONFLICT (inference_kind_id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, example_field = EXCLUDED.example_field, evidence_count = EXCLUDED.evidence_count, maturity = EXCLUDED.maturity, sort_order = EXCLUDED.sort_order;

INSERT INTO inference_kinds (inference_kind_id, title, description, example_field, evidence_count, maturity, sort_order)
VALUES ('ik-transitive-closure', 'Transitive closure (reachability inference)', 'Sparsely-asserted FromState->ToState edges imply the full reachability ordering, including never-asserted long-range pairs. The disease trajectory is inferred from the transition topology (e.g. intake -> actionable at hop 5, is_inferred=true) rather than hand-typed as an integer ladder - the autoimmune analogue of a step-1 -> step-5 ordering.', 'StateTransitionRules.ProgressionClosure (presymptomatic -> biopsy-indicated, inferred)', '1 closure field -> vw_state_transition_rules_closure: 14 asserted edges, 18 inferred pairs (to hop 5)', 'Live', 5) ON CONFLICT (inference_kind_id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, example_field = EXCLUDED.example_field, evidence_count = EXCLUDED.evidence_count, maturity = EXCLUDED.maturity, sort_order = EXCLUDED.sort_order;

INSERT INTO inference_kinds (inference_kind_id, title, description, example_field, evidence_count, maturity, sort_order)
VALUES ('ik-predicate-narrative', 'Predicate-gated narrative', 'Each raw fact is turned into a phrase by a per-row formula that selects wording from its own value and a shared __meta__ phrasebook (e.g. a temperature becomes ''normal'' | ''light fever'' | ''severe fever''). The diagnosis writeup is assembled from these inspectable cells - no free-text generated at render time.', 'Individuals.ActivityTier / TemperatureNarrative (banded from the row''s own value)', 'IF used 166x; per-row narrative fragment fields band raw values into language', 'Live', 6) ON CONFLICT (inference_kind_id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, example_field = EXCLUDED.example_field, evidence_count = EXCLUDED.evidence_count, maturity = EXCLUDED.maturity, sort_order = EXCLUDED.sort_order;

INSERT INTO inference_kinds (inference_kind_id, title, description, example_field, evidence_count, maturity, sort_order)
VALUES ('ik-cross-substrate-conformance', 'Cross-substrate conformance', 'The same declared model is projected to a second substrate (OWL) and an independent reasoner closes it on its own; agreement with the Postgres recursive view is the conformance receipt. rulebook-to-owl emits the transition relation as an owl:TransitiveProperty, owlrl deduces every reachable pair, and owl/reason.py diffs that set against vw_state_transition_rules_closure - they match exactly (32 reachability pairs, incl. the inferred long-range intake -> actionable at hop 5). A recursive SQL view and an OWL-RL deductive closure compute the same reachability from one model: the reasoning is substrate-independent, not SQL-specific.', 'owl/reason.py: owlrl closure of `progression` (TransitiveProperty) == vw_state_transition_rules_closure', 'OWL-RL closure == Postgres closure: 14 asserted edges, 18 inferred pairs, 32 total - identical sets, verified by owl/reason.py', 'Live', 7) ON CONFLICT (inference_kind_id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, example_field = EXCLUDED.example_field, evidence_count = EXCLUDED.evidence_count, maturity = EXCLUDED.maturity, sort_order = EXCLUDED.sort_order;

-- ----------------------------------------------------------------------------
-- OpenQuestions: Decisions still pending, captured so they are not silently re-litigated in a later session.
-- ----------------------------------------------------------------------------
INSERT INTO open_questions (open_question_id, question, context, resolution, is_resolved)
VALUES ('oq-publish-now', 'Publish README now as a design/thesis doc, or hold until the harness goes green?', 'Repo is at Loop 0.5 (harness red, no LLM intake yet). Receipts land harder green.', '', FALSE) ON CONFLICT (open_question_id) DO UPDATE SET question = EXCLUDED.question, context = EXCLUDED.context, resolution = EXCLUDED.resolution, is_resolved = EXCLUDED.is_resolved;

INSERT INTO open_questions (open_question_id, question, context, resolution, is_resolved)
VALUES ('oq-extract-vs-invent', 'Does the LLM extract facts present in the case, or invent plausible facts for a described case?', 'Mode #1 (extract) vs mode #2 (invent) changes how strong the claim is.', 'Mode #1 at intake (extract/interpret), and synthetic-but-transparent test results for the invented case — every number visible, sourced, editable.', TRUE) ON CONFLICT (open_question_id) DO UPDATE SET question = EXCLUDED.question, context = EXCLUDED.context, resolution = EXCLUDED.resolution, is_resolved = EXCLUDED.is_resolved;

INSERT INTO open_questions (open_question_id, question, context, resolution, is_resolved)
VALUES ('oq-reworded-prompt', 'Confirm the reworded README prompt shares no distinctive phrasing with the prospect''s original.', 'Anonymity / no verbatim leakage before publishing.', '', FALSE) ON CONFLICT (open_question_id) DO UPDATE SET question = EXCLUDED.question, context = EXCLUDED.context, resolution = EXCLUDED.resolution, is_resolved = EXCLUDED.is_resolved;

INSERT INTO open_questions (open_question_id, question, context, resolution, is_resolved)
VALUES ('oq-fragment-fields-where', 'On which tables do the narrative fragment fields live, and how are per-case fragments composed up into one report — section order, headers, grouping?', 'Decision is ''pure derived fields'': sentence wording is per-row calculated fields (cell-simple, predicate-gated), reusable atoms in __meta__. Still open: do fragments hang off the patient/IndividualPredictions row and reference sibling facts, or off each evidence/gate row and roll up as text? And the renderer owns only ordering/concatenation — confirm it never composes wording. This is the next loop''s design.', '', FALSE) ON CONFLICT (open_question_id) DO UPDATE SET question = EXCLUDED.question, context = EXCLUDED.context, resolution = EXCLUDED.resolution, is_resolved = EXCLUDED.is_resolved;

