VALUES ('ng-clinical-use', 'This is not validated clinical decision support and must never be used for clinical purposes.', 'Demonstration of inference structure only; all patients synthetic, all figures literature ranges.') ON CONFLICT (non_goal_id) DO UPDATE SET statement = EXCLUDED.statement, why_excluded = EXCLUDED.why_excluded;

INSERT INTO non_goals (non_goal_id, statement, why_excluded)
VALUES ('ng-crud-ui', 'This is not a CRUD UI.', 'The home screen is the witnessed red/green harness; the payoff is a derived diagnosis writeup.') ON CONFLICT (non_goal_id) DO UPDATE SET statement = EXCLUDED.statement, why_excluded = EXCLUDED.why_excluded;

INSERT INTO non_goals (non_goal_id, statement, why_excluded)
VALUES ('ng-llm-reasoning', 'The LLM does not perform higher-order reasoning or render the diagnosis.', 'All reasoning lives in the open, editable DAG; the LLM is intake clerk + lab only.') ON CONFLICT (non_goal_id) DO UPDATE SET statement = EXCLUDED.statement, why_excluded = EXCLUDED.why_excluded;

INSERT INTO non_goals (non_goal_id, statement, why_excluded)
VALUES ('ng-full-breadth', 'The full omics breadth (counterfactual trajectories, most modalities, epistasis, exposures) is not on the keystone''s dependency path.', 'Kept as deliberate sparse context for breadth; pulled onto the path only when it earns its place (anti-hallucination rule).') ON CONFLICT (non_goal_id) DO UPDATE SET statement = EXCLUDED.statement, why_excluded = EXCLUDED.why_excluded;

INSERT INTO non_goals (non_goal_id, statement, why_excluded)
VALUES ('ng-publish-verbatim', 'Never publish the prospect''s verbatim problem text.', 'Anonymity / good manners; the public artifact uses a reworded generic grand-challenge prompt.') ON CONFLICT (non_goal_id) DO UPDATE SET statement = EXCLUDED.statement, why_excluded = EXCLUDED.why_excluded;

-- ----------------------------------------------------------------------------
-- GlossaryTerms: Vocabulary coined in the gauntlet conversation, so the framing is shared and stable across sessions.
-- ----------------------------------------------------------------------------
INSERT INTO glossary_terms (glossary_term_id, term, definition)
VALUES ('gt-knob', 'knob', 'A literal, editable leaf value in the admin UI representing one choice the LLM (or a human) made; nudged, not re-prompted, when wrong.') ON CONFLICT (glossary_term_id) DO UPDATE SET term = EXCLUDED.term, definition = EXCLUDED.definition;

INSERT INTO glossary_terms (glossary_term_id, term, definition)
VALUES ('gt-intake-clerk-lab', 'intake clerk + lab', 'The only two roles the LLM plays: interpret intake facts (clerk) and produce the case''s test results (lab). Never the diagnostician.') ON CONFLICT (glossary_term_id) DO UPDATE SET term = EXCLUDED.term, definition = EXCLUDED.definition;

INSERT INTO glossary_terms (glossary_term_id, term, definition)
VALUES ('gt-line-in-dag', 'line in the DAG', 'The trust boundary, stated mechanically: fields with a formula belong to the model; raw-input leaf fields are the LLM''s or a human''s.') ON CONFLICT (glossary_term_id) DO UPDATE SET term = EXCLUDED.term, definition = EXCLUDED.definition;

INSERT INTO glossary_terms (glossary_term_id, term, definition)
VALUES ('gt-three-panel-witness', 'three-panel witness', 'Input case text | extracted facts with per-fact provenance | deterministic diagnosis + gate trace — the two halves checkable independently.') ON CONFLICT (glossary_term_id) DO UPDATE SET term = EXCLUDED.term, definition = EXCLUDED.definition;

INSERT INTO glossary_terms (glossary_term_id, term, definition)
VALUES ('gt-fake-but-transparent', 'fake-but-transparent', 'Test results are synthetic (the case is invented) but every number is visible, sourced to the case, and editable; nothing is hidden.') ON CONFLICT (glossary_term_id) DO UPDATE SET term = EXCLUDED.term, definition = EXCLUDED.definition;

INSERT INTO glossary_terms (glossary_term_id, term, definition)
VALUES ('gt-laundering-objection', 'laundering objection', 'The skeptic''s claim that a deterministic function over LLM-chosen inputs just launders a hallucination; defeated by externalized knobs + independent witness.') ON CONFLICT (glossary_term_id) DO UPDATE SET term = EXCLUDED.term, definition = EXCLUDED.definition;

INSERT INTO glossary_terms (glossary_term_id, term, definition)
VALUES ('gt-disease-state-simulator', 'disease state simulator', 'The v2 layer the audit asked for: disease modeled as a WITNESSED state machine whose transitions fire only on raw longitudinal observations (rising anti-dsDNA, falling C3/C4, proteinuria). Current state and dwell-time are derived & bitemporal — the contrast the audit drew with an ''evidence gate''.') ON CONFLICT (glossary_term_id) DO UPDATE SET term = EXCLUDED.term, definition = EXCLUDED.definition;

INSERT INTO glossary_terms (glossary_term_id, term, definition)
VALUES ('gt-evidence-gate', 'evidence gate', 'The v1 layer: per-patient adjudication of whether a prediction is trustworthy enough to act on (the four gates + IsClinicallyActionable). v2 keeps this and adds the disease-state simulator above it on the same hub.') ON CONFLICT (glossary_term_id) DO UPDATE SET term = EXCLUDED.term, definition = EXCLUDED.definition;

INSERT INTO glossary_terms (glossary_term_id, term, definition)
VALUES ('gt-disease-progression-machine', 'disease progression machine', 'A state machine on the polymorphic StateMachines substrate whose subject is a patient''s disease course (presymptomatic -> serologic-active -> early-nephritis -> renal-flare-risk -> biopsy-indicated). Transitions are raw-leaf-triggered; current state is the derived IsCurrent occupancy.') ON CONFLICT (glossary_term_id) DO UPDATE SET term = EXCLUDED.term, definition = EXCLUDED.definition;

INSERT INTO glossary_terms (glossary_term_id, term, definition)
VALUES ('gt-dwell-time', 'dwell time', 'Bitemporal derivation: how long a subject has been in a disease state (now - EnteredAt while current; ExitedAt - EnteredAt once left). The audit asked for ''how long has the patient/disease been in a state'' — this is that, as a formula.') ON CONFLICT (glossary_term_id) DO UPDATE SET term = EXCLUDED.term, definition = EXCLUDED.definition;

INSERT INTO glossary_terms (glossary_term_id, term, definition)
VALUES ('gt-serology-trajectory', 'serology trajectory', 'The raw longitudinal leaves driving progression: anti-dsDNA titre trend (rising/stable/falling), complement C3/C4 trend, proteinuria. The LLM/lab may emit these; everything above them is derived.') ON CONFLICT (glossary_term_id) DO UPDATE SET term = EXCLUDED.term, definition = EXCLUDED.definition;

INSERT INTO glossary_terms (glossary_term_id, term, definition)
VALUES ('gt-treatment-line-recommendation', 'treatment line recommendation', 'Derived field: given the patient''s confirmed causal mechanism + current disease state, the recommended therapy (MMF vs belimumab vs anifrolumab) and the single deciding reason. The audit''s second worked example.') ON CONFLICT (glossary_term_id) DO UPDATE SET term = EXCLUDED.term, definition = EXCLUDED.definition;

INSERT INTO glossary_terms (glossary_term_id, term, definition)
VALUES ('gt-corpus-discovery', 'corpus discovery', 'The cohort-level surface where causal-hypothesis patterns EMERGE across many patients (vs v1''s per-patient verdicts). Discovery is inherently corpus-level; this is the v2 reframe of the audit''s ''you don''t do discovery'' critique.') ON CONFLICT (glossary_term_id) DO UPDATE SET term = EXCLUDED.term, definition = EXCLUDED.definition;

-- ----------------------------------------------------------------------------
-- EffortlessLoops: The ordered Effortless loops that build this platform, as data. The derived plan (EFFORTLESS_LOOPS.md, via json-hbars-transform) is generated from these rows; completed ([DONE]) loops are pruned at publish so only current/roadmap work shows in the plan.
-- ----------------------------------------------------------------------------
