INSERT INTO effortless_loops (effortless_loop_id, loop_number, title, goal, status, rule_commit_msg, state_commit_msg, sort_order, status_badge, status_line)
VALUES ('loop-0-5', '0.5', 'Test Harness First (the red contract)', 'Ship a witnessed inference harness asserting the entire DAG x 7 patients via the app API; red on arrival, load-bearing.', 'done', 'none - app-only loop, test-harness-first, no rule change', 'state: Loop 0.5 - red witnessed-inference harness is the app''s contract', 1, '[DONE]', ' - rule `none - app-only loop, test-harness-first, no rule change`; state `state: Loop 0.5 - red witnessed-inference harness is the app''s contract`') ON CONFLICT (effortless_loop_id) DO UPDATE SET loop_number = EXCLUDED.loop_number, title = EXCLUDED.title, goal = EXCLUDED.goal, status = EXCLUDED.status, rule_commit_msg = EXCLUDED.rule_commit_msg, state_commit_msg = EXCLUDED.state_commit_msg, sort_order = EXCLUDED.sort_order, status_badge = EXCLUDED.status_badge, status_line = EXCLUDED.status_line;

INSERT INTO effortless_loops (effortless_loop_id, loop_number, title, goal, status, rule_commit_msg, state_commit_msg, sort_order, status_badge, status_line)
VALUES ('loop-1', '1', 'Intake app skeleton', 'Turn keystone-level red tests green: wire cohort + prediction-panel endpoints reading vw_*.', 'done', 'none - app-only loop, no rule change', 'state: Loop 1 - read-only intake app surfaces the keystone', 2, '[DONE]', ' - rule `none - app-only loop, no rule change`; state `state: Loop 1 - read-only intake app surfaces the keystone`') ON CONFLICT (effortless_loop_id) DO UPDATE SET loop_number = EXCLUDED.loop_number, title = EXCLUDED.title, goal = EXCLUDED.goal, status = EXCLUDED.status, rule_commit_msg = EXCLUDED.rule_commit_msg, state_commit_msg = EXCLUDED.state_commit_msg, sort_order = EXCLUDED.sort_order, status_badge = EXCLUDED.status_badge, status_line = EXCLUDED.status_line;

INSERT INTO effortless_loops (effortless_loop_id, loop_number, title, goal, status, rule_commit_msg, state_commit_msg, sort_order, status_badge, status_line)
VALUES ('loop-2', '2', 'Patient intake (facts in)', 'Form writes a new Individual + child observation rows to base tables, then re-reads the derived panel. The knob-editing payoff.', 'done', 'rule (if any) for new intake field', 'state: Loop 2 - facts-in to derived diagnosis works end to end', 3, '[DONE]', ' - rule `rule (if any) for new intake field`; state `state: Loop 2 - facts-in to derived diagnosis works end to end`') ON CONFLICT (effortless_loop_id) DO UPDATE SET loop_number = EXCLUDED.loop_number, title = EXCLUDED.title, goal = EXCLUDED.goal, status = EXCLUDED.status, rule_commit_msg = EXCLUDED.rule_commit_msg, state_commit_msg = EXCLUDED.state_commit_msg, sort_order = EXCLUDED.sort_order, status_badge = EXCLUDED.status_badge, status_line = EXCLUDED.status_line;

INSERT INTO effortless_loops (effortless_loop_id, loop_number, title, goal, status, rule_commit_msg, state_commit_msg, sort_order, status_badge, status_line)
VALUES ('loop-3', '3', '3-panel witness — provenance back into the case text', 'Show why each gate passed/failed one level down; consider installing the explainer-DAG transpiler.', 'done', 'rule: install explainer-dag', 'state: Loop 3 - gate explainability', 4, '[DONE]', ' - rule `rule: install explainer-dag`; state `state: Loop 3 - gate explainability`') ON CONFLICT (effortless_loop_id) DO UPDATE SET loop_number = EXCLUDED.loop_number, title = EXCLUDED.title, goal = EXCLUDED.goal, status = EXCLUDED.status, rule_commit_msg = EXCLUDED.rule_commit_msg, state_commit_msg = EXCLUDED.state_commit_msg, sort_order = EXCLUDED.sort_order, status_badge = EXCLUDED.status_badge, status_line = EXCLUDED.status_line;

INSERT INTO effortless_loops (effortless_loop_id, loop_number, title, goal, status, rule_commit_msg, state_commit_msg, sort_order, status_badge, status_line)
VALUES ('loop-4', '4', 'Second prediction type (severity)', 'Add a derived severity prediction grounded in ClinicalPhenotypes.SeverityScore; pull one context table onto the load-bearing path.', 'done', 'rule: derive a severity prediction (IsSeverityActionable) chained to the onset gates', 'state: Loop 4 - severity prediction (second prediction type) green', 5, '[DONE]', ' - rule `rule: derive a severity prediction (IsSeverityActionable) chained to the onset gates`; state `state: Loop 4 - severity prediction (second prediction type) green`') ON CONFLICT (effortless_loop_id) DO UPDATE SET loop_number = EXCLUDED.loop_number, title = EXCLUDED.title, goal = EXCLUDED.goal, status = EXCLUDED.status, rule_commit_msg = EXCLUDED.rule_commit_msg, state_commit_msg = EXCLUDED.state_commit_msg, sort_order = EXCLUDED.sort_order, status_badge = EXCLUDED.status_badge, status_line = EXCLUDED.status_line;

INSERT INTO effortless_loops (effortless_loop_id, loop_number, title, goal, status, rule_commit_msg, state_commit_msg, sort_order, status_badge, status_line)
VALUES ('loop-5', '5', 'Treatment-response prediction', 'Derive a treatment-response prediction from Treatments + mechanism match; surface in the panel.', 'done', 'rule: derive a treatment-response prediction (IsTreatmentResponseActionable) via mechanism match', 'state: Loop 5 - treatment-response prediction (third prediction type) green', 6, '[DONE]', ' - rule `rule: derive a treatment-response prediction (IsTreatmentResponseActionable) via mechanism match`; state `state: Loop 5 - treatment-response prediction (third prediction type) green`') ON CONFLICT (effortless_loop_id) DO UPDATE SET loop_number = EXCLUDED.loop_number, title = EXCLUDED.title, goal = EXCLUDED.goal, status = EXCLUDED.status, rule_commit_msg = EXCLUDED.rule_commit_msg, state_commit_msg = EXCLUDED.state_commit_msg, sort_order = EXCLUDED.sort_order, status_badge = EXCLUDED.status_badge, status_line = EXCLUDED.status_line;

INSERT INTO effortless_loops (effortless_loop_id, loop_number, title, goal, status, rule_commit_msg, state_commit_msg, sort_order, status_badge, status_line)
VALUES ('loop-vocab-completeness', '6', 'Vocabulary completeness - every audit-named concept enters the hub', 'Answer the audit''s breadth: bring every concept the physician named (lupus nephritis, NPSLE, cutaneous lupus, sero+/-RA, erosive disease, axial PsA, enthesitis, dactylitis, uveitis, IBD overlap, organ damage, flare patterns, treatment lines, SLEDAI/DAS28) into the hub as DiseaseDomainConcepts, each with an honest ModelingStatus (deep-DAG / schema / vocabulary). Coverage becomes checkable by grep, not by trust.', 'done', 'rule: DiseaseDomainConcepts - every audit-named concept in the hub with honest ModelingStatus', 'state: v2 step1 - vocabulary completeness; coverage checkable by grep', 7, '[DONE]', ' - rule `rule: DiseaseDomainConcepts - every audit-named concept in the hub with honest ModelingStatus`; state `state: v2 step1 - vocabulary completeness; coverage checkable by grep`') ON CONFLICT (effortless_loop_id) DO UPDATE SET loop_number = EXCLUDED.loop_number, title = EXCLUDED.title, goal = EXCLUDED.goal, status = EXCLUDED.status, rule_commit_msg = EXCLUDED.rule_commit_msg, state_commit_msg = EXCLUDED.state_commit_msg, sort_order = EXCLUDED.sort_order, status_badge = EXCLUDED.status_badge, status_line = EXCLUDED.status_line;

INSERT INTO effortless_loops (effortless_loop_id, loop_number, title, goal, status, rule_commit_msg, state_commit_msg, sort_order, status_badge, status_line)
VALUES ('loop-disease-state', '7', 'Disease-state simulator - the layer the audit said did not exist', 'Reframe: v1 was a per-patient evidence gate; v2 adds the disease-state layer. A disease progressing is a state machine (lupus-nephritis-progression: Presymptomatic then SerologicActive then EarlyNephritis then RenalFlareRisk then BiopsyIndicated) whose CURRENT state is DERIVED purely from raw serology leaves (rising anti-dsDNA + falling complement + proteinuria + sediment) - never hand-set. Bitemporal DwellDays answers the audit''s ''how long in this state.'' Same trust boundary: labs are the LLM''s/clinician''s, the state is the model''s. Diego Santos''s first worked example computes (derived SledaiScore 12, High/flare).', 'done', 'rule: lupus-nephritis-progression state machine - disease state DERIVED from raw serology', 'state: v2 step3 - disease-state simulator; harness green, counter-example witnessed', 8, '[DONE]', ' - rule `rule: lupus-nephritis-progression state machine - disease state DERIVED from raw serology`; state `state: v2 step3 - disease-state simulator; harness green, counter-example witnessed`') ON CONFLICT (effortless_loop_id) DO UPDATE SET loop_number = EXCLUDED.loop_number, title = EXCLUDED.title, goal = EXCLUDED.goal, status = EXCLUDED.status, rule_commit_msg = EXCLUDED.rule_commit_msg, state_commit_msg = EXCLUDED.state_commit_msg, sort_order = EXCLUDED.sort_order, status_badge = EXCLUDED.status_badge, status_line = EXCLUDED.status_line;

INSERT INTO effortless_loops (effortless_loop_id, loop_number, title, goal, status, rule_commit_msg, state_commit_msg, sort_order, status_badge, status_line)
VALUES ('loop-treatment-line', '8', 'Treatment-line recommendation + the disagreement counter-example', 'The audit''s second worked example, computed: a derived RecommendedTreatmentLine + single TreatmentLineDecidingFactor (mycophenolate for active nephritis, anifrolumab for type-I-IFN, belimumab for autoantibody-driven, secukinumab for IL-17/23) - differentiated by confirmed mechanism x disease state, never by a label. The load-bearing proof: Diego is progression_vs_actionability_disagree = TRUE - the disease-state simulator says he IS progressing (BiopsyIndicated, high activity) while the actionability gate says NOT actionable (cryptic-relatedness leakage). A pure evidence gate could never produce that sentence; that it can is the proof v2 != v1 relabeled.', 'done', 'rule: RecommendedTreatmentLine + progression_vs_actionability_disagree counter-example', 'state: v2 - treatment-line + disagreement; the two layers proven independent', 9, '[DONE]', ' - rule `rule: RecommendedTreatmentLine + progression_vs_actionability_disagree counter-example`; state `state: v2 - treatment-line + disagreement; the two layers proven independent`') ON CONFLICT (effortless_loop_id) DO UPDATE SET loop_number = EXCLUDED.loop_number, title = EXCLUDED.title, goal = EXCLUDED.goal, status = EXCLUDED.status, rule_commit_msg = EXCLUDED.rule_commit_msg, state_commit_msg = EXCLUDED.state_commit_msg, sort_order = EXCLUDED.sort_order, status_badge = EXCLUDED.status_badge, status_line = EXCLUDED.status_line;

INSERT INTO effortless_loops (effortless_loop_id, loop_number, title, goal, status, rule_commit_msg, state_commit_msg, sort_order, status_badge, status_line)
VALUES ('loop-cohort-discovery', '9', 'Cohort discovery board - the corpus-level surface', 'The doctor''s deepest point: discovery is corpus-level - a single chart never discovers a mechanism, a pattern across many patients does. Build the top-level, all-roles Cohort discovery board over a 12-member claim-bearing cohort: the disease-state map, the emergent serology-signature scatter, the disease-vs-evidence disagreement board, and the treatment-line distribution - all reading derived fields. Per-patient progression + treatment-line tabs hang off the same model. The punchline, sorted to the top of the nav.', 'done', 'rule: 12-member cohort expansion; corpus-level derived fields for the discovery board', 'state: v2 steps9-10 - Cohort discovery is the top-level all-roles nav item', 10, '[DONE]', ' - rule `rule: 12-member cohort expansion; corpus-level derived fields for the discovery board`; state `state: v2 steps9-10 - Cohort discovery is the top-level all-roles nav item`') ON CONFLICT (effortless_loop_id) DO UPDATE SET loop_number = EXCLUDED.loop_number, title = EXCLUDED.title, goal = EXCLUDED.goal, status = EXCLUDED.status, rule_commit_msg = EXCLUDED.rule_commit_msg, state_commit_msg = EXCLUDED.state_commit_msg, sort_order = EXCLUDED.sort_order, status_badge = EXCLUDED.status_badge, status_line = EXCLUDED.status_line;

INSERT INTO effortless_loops (effortless_loop_id, loop_number, title, goal, status, rule_commit_msg, state_commit_msg, sort_order, status_badge, status_line)
VALUES ('loop-progression-admin', '10', 'Progression machine in the state-machine admin', 'The one concrete unbuilt admin-witness item. StateMachineView is hardcoded to diagnosis-lifecycle; lupus-nephritis-progression already lives in vw_state_machines and is served by the same router. Make StateMachineView select the machine (a binding change, not a model change): render its states, the 5 raw-leaf-triggered transition rules, and a per-state cohort-occupancy strip. Closes the loop between the disease-state simulator and its admin witness.', 'done', 'none - app-only loop; occupancy already derived (IsCurrent), admin-witness binding only', 'state: Loop 10 - progression machine bound into the state-machine admin; per-state cohort occupancy is the simulator''s admin witness', 11, '[DONE]', ' - rule `none - app-only loop; occupancy already derived (IsCurrent), admin-witness binding only`; state `state: Loop 10 - progression machine bound into the state-machine admin; per-state cohort occupancy is the simulator''s admin witness`') ON CONFLICT (effortless_loop_id) DO UPDATE SET loop_number = EXCLUDED.loop_number, title = EXCLUDED.title, goal = EXCLUDED.goal, status = EXCLUDED.status, rule_commit_msg = EXCLUDED.rule_commit_msg, state_commit_msg = EXCLUDED.state_commit_msg, sort_order = EXCLUDED.sort_order, status_badge = EXCLUDED.status_badge, status_line = EXCLUDED.status_line;

INSERT INTO effortless_loops (effortless_loop_id, loop_number, title, goal, status, rule_commit_msg, state_commit_msg, sort_order, status_badge, status_line)
VALUES ('loop-serology-discovery', '11', 'Serology-signature discovery - emergent cluster, not a label', 'Make the discovery claim falsifiable at corpus scale. The serology signature that PRECEDES nephritis (the rising-anti-dsDNA / falling-complement trajectory) should surface as a DERIVED corpus-level cluster on the cohort scatter - emergent from the population''s raw serology series, not a label anyone assigned. Derive the cluster membership / signature-strength field in the hub so the discovery is reproducible and witnessed, then surface it on the cohort board. This is the literal answer to ''discovery is corpus-level.''', 'done', 'rule: derive emergent pre-nephritic serology-signature cluster (IsPreNephriticSignaturePanel -> CountPreNephriticSignaturePanels -> IsInPreNephriticSignatureCluster + SignatureStrength)', 'state: Loop 11 - emergent serology-signature cluster; 6/12 in cluster, perfectly separating active/progressing from quiescent; surfaced as derived halo on the cohort scatter', 12, '[DONE]', ' - rule `rule: derive emergent pre-nephritic serology-signature cluster (IsPreNephriticSignaturePanel -> CountPreNephriticSignaturePanels -> IsInPreNephriticSignatureCluster + SignatureStrength)`; state `state: Loop 11 - emergent serology-signature cluster; 6/12 in cluster, perfectly separating active/progressing from quiescent; surfaced as derived halo on the cohort scatter`') ON CONFLICT (effortless_loop_id) DO UPDATE SET loop_number = EXCLUDED.loop_number, title = EXCLUDED.title, goal = EXCLUDED.goal, status = EXCLUDED.status, rule_commit_msg = EXCLUDED.rule_commit_msg, state_commit_msg = EXCLUDED.state_commit_msg, sort_order = EXCLUDED.sort_order, status_badge = EXCLUDED.status_badge, status_line = EXCLUDED.status_line;

INSERT INTO effortless_loops (effortless_loop_id, loop_number, title, goal, status, rule_commit_msg, state_commit_msg, sort_order, status_badge, status_line)
VALUES ('loop-prune-nonloadbearing', '12', 'Prune excess engineering - keep only what is load-bearing for the v1 audit response', 'A deliberate trimming pass (NOT a delete spree). Walk the model, the app, and the docs and find anything that was UPGRADED or SUPERSEDED and now lingers as a duplicate, plus any engineering that is not actually load-bearing toward the clearest pedagogical answer to the v1 audit. Candidates to scrutinise: superseded prediction types that don''t earn their keep (e.g. a 4th parallel adverse-effect prediction once severity + treatment-response + treatment-line exist), redundant ontology slots that no longer carry a claim, and any view/endpoint with no consumer. Promotion rule inverted: if a thing is neither traceable to problem-to-solve.md nor load-bearing toward the keystone or the audit response, retire it. Goal: the clearest, most complete, DUPLICATE-FREE representation of the problem - so the audit response is concise as well as complete.', 'done', 'none - verification loop, no rule change; inventory found nothing load-bearing to retire', 'state: Loop 12 - verified lean. Every endpoint is consumed (client or witnessed harness); no 4th adverse-effect prediction exists; the 3 zero-ref context tables (CounterfactualTrajectories/EnvironmentalExposures/TherapyOptions) are each named in problem-to-solve.md so they stay as honest schema coverage; no duplicate ontology slots or dead calc fields. The inverted promotion rule held: nothing is neither-traceable-nor-load-bearing.', 13, '[DONE]', ' - rule `none - verification loop, no rule change; inventory found nothing load-bearing to retire`; state `state: Loop 12 - verified lean. Every endpoint is consumed (client or witnessed harness); no 4th adverse-effect prediction exists; the 3 zero-ref context tables are each named in problem-to-solve.md so they stay as honest schema coverage; no duplicate ontology slots or dead calc fields.`') ON CONFLICT (effortless_loop_id) DO UPDATE SET loop_number = EXCLUDED.loop_number, title = EXCLUDED.title, goal = EXCLUDED.goal, status = EXCLUDED.status, rule_commit_msg = EXCLUDED.rule_commit_msg, state_commit_msg = EXCLUDED.state_commit_msg, sort_order = EXCLUDED.sort_order, status_badge = EXCLUDED.status_badge, status_line = EXCLUDED.status_line;

INSERT INTO effortless_loops (effortless_loop_id, loop_number, title, goal, status, rule_commit_msg, state_commit_msg, sort_order, status_badge, status_line)
VALUES ('loop-llm-intake', '13', 'LLM intake clerk + synthetic lab', 'FUTURE ROADMAP (not part of the v1-audit response - this is the framework-thesis deliverable, the next conversation). The trust-boundary payoff: wire the LLM to read a natural-language case and write ONLY leaf observations - intake facts + synthetic-but-transparent test results - with the three-panel witness (case text / extracted facts with per-fact provenance / derived diagnosis + gate trace). The LLM never computes a higher-order inference; every value it emits is an editable knob. Demotes the model to a replaceable, fully-overridable transcriber - the structural defeat of ''a hallucination laundered through a deterministic function.''', 'roadmap', 'rule (if any) for provenance fields', 'state: LLM intake clerk, everything-is-a-knob', 14, '[ROADMAP]', '') ON CONFLICT (effortless_loop_id) DO UPDATE SET loop_number = EXCLUDED.loop_number, title = EXCLUDED.title, goal = EXCLUDED.goal, status = EXCLUDED.status, rule_commit_msg = EXCLUDED.rule_commit_msg, state_commit_msg = EXCLUDED.state_commit_msg, sort_order = EXCLUDED.sort_order, status_badge = EXCLUDED.status_badge, status_line = EXCLUDED.status_line;

INSERT INTO effortless_loops (effortless_loop_id, loop_number, title, goal, status, rule_commit_msg, state_commit_msg, sort_order, status_badge, status_line)
VALUES ('loop-equity', '14', 'Cohort-level equity report', 'FUTURE ROADMAP (traceable to the original challenge''s equity requirement, but not part of the v1-audit response). Ancestry-equity made structural and corpus-level: calibration and actionability rates by ancestry (gates 2 and 4 of the keystone) as a derived dashboard, complementing the cohort discovery board. Equity is a checkable rate, not a promise.', 'roadmap', '', '', 15, '[ROADMAP]', '') ON CONFLICT (effortless_loop_id) DO UPDATE SET loop_number = EXCLUDED.loop_number, title = EXCLUDED.title, goal = EXCLUDED.goal, status = EXCLUDED.status, rule_commit_msg = EXCLUDED.rule_commit_msg, state_commit_msg = EXCLUDED.state_commit_msg, sort_order = EXCLUDED.sort_order, status_badge = EXCLUDED.status_badge, status_line = EXCLUDED.status_line;

