VALUES ('diagnosis-lifecycle', 'Diagnosis Lifecycle', 'Walks each case from Intake through the four gates to a terminal Actionable / NotActionable verdict. Each patient branches at its single deciding gate. Current state is DERIVED (IndividualPredictions.LifecycleStateKey); the transition log is the witnessed history.', 'IndividualPredictions', 'LifecycleStateKey', NULL, NULL, NULL, NULL, 'build-seed', NULL, 'build-seed', NULL) ON CONFLICT (state_machine_id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, subject_table_name = EXCLUDED.subject_table_name, subject_state_column = EXCLUDED.subject_state_column, machine_states = EXCLUDED.machine_states, state_transition_rules = EXCLUDED.state_transition_rules, state_transitions = EXCLUDED.state_transitions, created_at = EXCLUDED.created_at, created_by = EXCLUDED.created_by, modified_at = EXCLUDED.modified_at, modified_by = EXCLUDED.modified_by, modified_by_model = EXCLUDED.modified_by_model;

