VALUES ('lupus-nephritis-progression', 'Lupus-Nephritis Progression', 'Disease-state simulator: a patient''s lupus-nephritis course derived from raw serology trajectories. Presymptomatic -> SerologicActive -> EarlyNephritis -> RenalFlareRisk -> BiopsyIndicated (+ Quiescent). Current state is the derived Individuals.NephritisProgressionStateKey; never hand-set.', 'Individuals', 'NephritisProgressionStateKey', NULL, NULL, NULL, '2026-06-20T00:00:00Z', 'v2-step3', '2026-06-20T00:00:00Z', 'v2-step3', 'claude-opus-4-8') ON CONFLICT (state_machine_id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, subject_table_name = EXCLUDED.subject_table_name, subject_state_column = EXCLUDED.subject_state_column, machine_states = EXCLUDED.machine_states, state_transition_rules = EXCLUDED.state_transition_rules, state_transitions = EXCLUDED.state_transitions, created_at = EXCLUDED.created_at, created_by = EXCLUDED.created_by, modified_at = EXCLUDED.modified_at, modified_by = EXCLUDED.modified_by, modified_by_model = EXCLUDED.modified_by_model;

