INSERT INTO disease_domain_concepts (disease_domain_concept_id, concept_label, related_disease, modeling_status, definition, challenge_stressor_type)
VALUES ('lupus-nephritis', 'Lupus Nephritis', 'SLE', 'deep-dag', 'Renal involvement of SLE; immune-complex glomerulonephritis. v2 models its PROGRESSION as a witnessed state machine driven by rising anti-dsDNA + falling complement + proteinuria.', 'disease-progression / organ-specific subtype') ON CONFLICT (disease_domain_concept_id) DO UPDATE SET concept_label = EXCLUDED.concept_label, related_disease = EXCLUDED.related_disease, modeling_status = EXCLUDED.modeling_status, definition = EXCLUDED.definition, challenge_stressor_type = EXCLUDED.challenge_stressor_type;

