VALUES ('treatment-line-selection', 'Treatment-Line Selection', 'SLE', 'deep-dag', 'Which therapy to choose given the patient''s causal mechanism + disease state: mycophenolate (MMF) vs belimumab vs anifrolumab. v2 derives a recommended line + single deciding reason.', 'treatment response / patient stratification') ON CONFLICT (disease_domain_concept_id) DO UPDATE SET concept_label = EXCLUDED.concept_label, related_disease = EXCLUDED.related_disease, modeling_status = EXCLUDED.modeling_status, definition = EXCLUDED.definition, challenge_stressor_type = EXCLUDED.challenge_stressor_type;

